{
  "name": "codeguide",
  "displayName": "CodeGuide",
  "version": "0.1.0",
  "description": "AI-powered guided code explanation for VS Code",
  "publisher": "codeguide",
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Education",
    "Programming Languages",
    "Other"
  ],
  "keywords": [
    "code",
    "guide",
    "explain",
    "ai",
    "claude",
    "learning"
  ],
  "activationEvents": [],
  "main": "./dist/extension.js",
  "contributes": {
    "commands": [
      {
        "command": "codeguide.startGuide",
        "title": "CodeGuide: Start Guided Learning",
        "icon": "$(book)"
      },
      {
        "command": "codeguide.explainFile",
        "title": "CodeGuide: Explain Current File",
        "icon": "$(info)"
      },
      {
        "command": "codeguide.explainSelection",
        "title": "CodeGuide: Explain Selection",
        "icon": "$(comment-discussion)"
      },
      {
        "command": "codeguide.askQuestion",
        "title": "CodeGuide: Ask Question",
        "icon": "$(question)"
      },
      {
        "command": "codeguide.nextStep",
        "title": "CodeGuide: Next Step",
        "icon": "$(arrow-right)"
      },
      {
        "command": "codeguide.previousStep",
        "title": "CodeGuide: Previous Step",
        "icon": "$(arrow-left)"
      },
      {
        "command": "codeguide.stopGuide",
        "title": "CodeGuide: Stop Guide",
        "icon": "$(close)"
      }
    ],
    "viewsContainers": {
      "activitybar": [
        {
          "id": "codeguide",
          "title": "CodeGuide",
          "icon": "media/codeguide.svg"
        }
      ]
    },
    "views": {
      "codeguide": [
        {
          "type": "webview",
          "id": "codeguide.sidebar",
          "name": "Explanation"
        },
        {
          "id": "codeguide.learningPath",
          "name": "Learning Path"
        }
      ]
    },
    "configuration": {
      "title": "CodeGuide",
      "properties": {
        "codeguide.configSource": {
          "type": "string",
          "default": "claude-code",
          "enum": ["claude-code", "manual"],
          "enumDescriptions": [
            "Auto-read from Claude Code (~/.claude/settings.json)",
            "Use manual configuration below"
          ],
          "description": "Where to read API configuration from"
        },
        "codeguide.apiKey": {
          "type": "string",
          "default": "",
          "description": "API key (only used when configSource is 'manual')"
        },
        "codeguide.baseUrl": {
          "type": "string",
          "default": "",
          "description": "API base URL (only used when configSource is 'manual'). E.g. https://api.anthropic.com, or your proxy URL"
        },
        "codeguide.model": {
          "type": "string",
          "default": "",
          "description": "Model name (only used when configSource is 'manual'). Leave empty to use default"
        },
        "codeguide.maxTokens": {
          "type": "number",
          "default": 4096,
          "description": "Maximum tokens for AI responses"
        }
      }
    }
  },
  "scripts": {
    "vscode:prepublish": "npm run esbuild-base",
    "esbuild-base": "esbuild ./src/extension.ts --bundle --outfile=dist/extension.js --external:vscode --format=cjs --platform=node --target=node18",
    "compile": "npm run esbuild-base",
    "watch": "esbuild ./src/extension.ts --bundle --outfile=dist/extension.js --external:vscode --format=cjs --platform=node --target=node18 --watch",
    "package": "vsce package"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^0.78.0",
    "globby": "^16.1.1"
  },
  "devDependencies": {
    "@types/node": "^25.3.3",
    "@types/vscode": "^1.85.0",
    "@vscode/vsce": "^2.22.0",
    "esbuild": "^0.27.3",
    "typescript": "^5.9.3"
  },
  "license": "MIT"
}

