import { ipcMain, BrowserWindow } from 'electron'
import { ClaudeClient } from '../../../core/ai/ClaudeClient'
import { readConfig, getEffectiveConfig } from '../../../core/utils/configReader'
import * as fs from 'fs/promises'
import * as path from 'path'
import * as os from 'os'
import log from 'electron-log'

let claudeClient: ClaudeClient | null = null

function getClient(): ClaudeClient {
  if (!claudeClient) {
    const config = getEffectiveConfig()
    claudeClient = new ClaudeClient({
      apiKey: config.apiKey,
      baseUrl: config.baseUrl,
      model: config.model,
      maxTokens: config.maxTokens
    })
  }
  return claudeClient
}

const CONFIG_PATH = path.join(os.homedir(), '.readcode', 'config.json')

async function ensureConfigDir(): Promise<void> {
  const dir = path.dirname(CONFIG_PATH)
  await fs.mkdir(dir, { recursive: true })
}

export function registerAIHandlers(): void {
  // Complete (non-streaming)
  ipcMain.handle('ai:complete', async (_event, systemPrompt: string, userPrompt: string) => {
    try {
      log.info('AI complete request')
      const client = getClient()
      const response = await client.complete(systemPrompt, userPrompt)
      return response
    } catch (error) {
      log.error('AI complete error:', error)
      throw error
    }
  })

  // Stream
  ipcMain.handle('ai:stream', async (event, systemPrompt: string, userPrompt: string) => {
    try {
      log.info('AI stream request')
      const client = getClient()

      const window = BrowserWindow.fromWebContents(event.sender)

      await client.stream(
        systemPrompt,
        userPrompt,
        (chunk) => {
          window?.webContents.send('ai:streamChunk', chunk)
        },
        (error) => {
          window?.webContents.send('ai:streamError', error.message)
        }
      )

      window?.webContents.send('ai:streamDone')
    } catch (error: any) {
      log.error('AI stream error:', error)
      event.sender.send('ai:streamError', error.message)
    }
  })

  // Get config
  ipcMain.handle('ai:getConfig', async () => {
    try {
      await ensureConfigDir()
      const configData = await fs.readFile(CONFIG_PATH, 'utf-8')
      return JSON.parse(configData)
    } catch {
      // Return default config
      const claudeConfig = readConfig()
      return {
        apiKey: claudeConfig.apiKey || '',
        baseUrl: claudeConfig.baseUrl || 'https://api.anthropic.com',
        model: claudeConfig.model || 'claude-sonnet-4-20250514',
        maxTokens: 4096
      }
    }
  })

  // Update config
  ipcMain.handle('ai:updateConfig', async (_event, config: any) => {
    try {
      await ensureConfigDir()
      await fs.writeFile(CONFIG_PATH, JSON.stringify(config, null, 2))
      // Reset client to use new config
      claudeClient = null
    } catch (error) {
      log.error('AI config update error:', error)
      throw error
    }
  })
}

