/**
 * VS Code extension - use native fetch when available
 */

// Check if fetch is available (VS Code 1.85+)
const hasNativeFetch = typeof fetch !== 'undefined';

export interface AIClientConfig {
  apiKey: string;
  baseUrl?: string;
  model?: string;
  maxTokens?: number;
}

/**
 * Simple HTTP/HTTPS request using native fetch or Node.js fallback
 */
async function simpleFetchRequest(
  url: string,
  options: {
    method?: string;
    headers?: Record<string, string>;
    body?: string;
  } = {},
  timeout: number = 180000
): Promise<{ status: number; statusText: string; headers: Record<string, string>; body: string }> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
    const response = await fetch(url, {
      method: options.method || 'POST',
      headers: options.headers,
      body: options.body,
      signal: controller.signal,
    });

    const body = await response.text();

    clearTimeout(timeoutId);

    return {
      status: response.status,
      statusText: response.statusText,
      headers: Object.fromEntries(response.headers.entries()),
      body,
    };
  } catch (error) {
    clearTimeout(timeoutId);
    throw error;
  }
}

/**
 * Retry wrapper with exponential backoff
 */
async function requestWithRetry(
  url: string,
  options: any,
  maxRetries: number = 3
): Promise<{ status: number; statusText: string; headers: Record<string, string>; body: string }> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      console.log(`[ClaudeClient] Request attempt ${attempt}/${maxRetries}`);
      return await simpleFetchRequest(url, options);
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
      console.error(`[ClaudeClient] Attempt ${attempt} failed:`, lastError.message);

      if (lastError.name === 'AbortError') {
        throw new Error('Request timeout');
      }

      if (attempt < maxRetries) {
        const waitTime = Math.pow(2, attempt) * 1000;
        console.log(`[ClaudeClient] Waiting ${waitTime}ms before retry...`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
      }
    }
  }

  throw lastError;
}

export class ClaudeClient {
  private apiKey: string;
  private baseUrl: string;
  private model: string;
  private maxTokens: number;

  constructor(config: AIClientConfig) {
    if (!config.apiKey) {
      throw new Error('API key is required');
    }

    this.apiKey = config.apiKey;
    this.baseUrl = config.baseUrl || 'https://api.anthropic.com';
    if (!this.baseUrl.startsWith('http')) {
      this.baseUrl = 'https://' + this.baseUrl;
    }

    this.model = config.model ?? 'claude-sonnet-4-20250514';
    this.maxTokens = config.maxTokens ?? 4096;

    console.log('[ClaudeClient] Initialized with baseUrl:', this.baseUrl);
    console.log('[ClaudeClient] Using native fetch:', hasNativeFetch);
  }

  async complete(systemPrompt: string, userPrompt: string): Promise<string> {
    const timeout = userPrompt.length > 10000 ? 300000 : 180000;

    console.log('[ClaudeClient] Sending request, prompt size:', userPrompt.length, 'chars');

    const requestBody = JSON.stringify({
      model: this.model,
      max_tokens: this.maxTokens,
      system: systemPrompt,
      messages: [
        {
          role: 'user',
          content: userPrompt,
        },
      ],
    });

    try {
      const response = await requestWithRetry(
        `${this.baseUrl}/v1/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': this.apiKey,
            'anthropic-version': '2023-06-01',
          },
          body: requestBody,
        },
        3
      );

      console.log('[ClaudeClient] Response status:', response.status);

      if (response.status !== 200) {
        const errorBody = JSON.parse(response.body || '{}');
        throw new Error(`API error (${response.status}): ${errorBody.error?.message || response.statusText}`);
      }

      const data = JSON.parse(response.body);

      if (!data.content || data.content.length === 0) {
        throw new Error('No response content received');
      }

      const textContent = data.content.find((block: any) => block.type === 'text');
      if (!textContent) {
        throw new Error('No text content in response');
      }

      console.log('[ClaudeClient] Response received:', data.id);
      return textContent.text;
    } catch (error) {
      console.error('[ClaudeClient] Error:', error);
      if (error instanceof Error) {
        throw new Error(`Failed to get completion: ${error.message}`);
      }
      throw new Error(`Failed to get completion: ${String(error)}`);
    }
  }

  async *stream(systemPrompt: string, userPrompt: string): AsyncGenerator<string> {
    throw new Error('Streaming not implemented');
  }
}

