export class ClaudeClient {
  private apiKey: string
  private baseUrl: string
  private model: string
  private maxTokens: number

  constructor(config: AIClientConfig) {
    if (!config.apiKey) {
      throw new Error('API key is required')
    }

    this.apiKey = config.apiKey
    this.baseUrl = config.baseUrl || 'https://api.anthropic.com'
    if (!this.baseUrl.startsWith('http')) {
      this.baseUrl = 'https://' + this.baseUrl
    }

    this.model = config.model ?? 'claude-sonnet-4-20250514'
    this.maxTokens = config.maxTokens ?? 4096

    console.log('[ClaudeClient] Initialized with baseUrl:', this.baseUrl)
  }

  async complete(systemPrompt: string, userPrompt: string): Promise<string> {
    const timeout = userPrompt.length > 10000 ? 300000 : 180000

    console.log('[ClaudeClient] Sending request, prompt size:', userPrompt.length, 'chars')

    const requestBody = JSON.stringify({
      model: this.model,
      max_tokens: this.maxTokens,
      system: systemPrompt,
      messages: [
        {
          role: 'user',
          content: userPrompt,
        },
      ],
    })

    try {
      const response = await requestWithRetry(
        `${this.baseUrl}/v1/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': this.apiKey,
            'anthropic-version': '2023-06-01',
          },
          body: requestBody,
        },
        3
      )

      console.log('[ClaudeClient] Response status:', response.status)

      if (response.status !== 200) {
        const errorBody = JSON.parse(response.body || '{}')
        throw new Error(`API error (${response.status}): ${errorBody.error?.message || response.statusText}`)
      }

      const data = JSON.parse(response.body)

      if (!data.content || data.content.length === 0) {
        throw new Error('No response content received')
      }

      const textContent = data.content.find((block: any) => block.type === 'text')
      if (!textContent) {
        throw new Error('No text content in response')
      }

      console.log('[ClaudeClient] Response received:', data.id)
      return textContent.text
    } catch (error) {
      console.error('[ClaudeClient] Error:', error)
      if (error instanceof Error) {
        throw new Error(`Failed to get completion: ${error.message}`)
      }
      throw new Error(`Failed to get completion: ${String(error)}`)
    }
  }

  async stream(
    systemPrompt: string,
    userPrompt: string,
    onChunk: (chunk: string) => void,
    onError: (error: Error) => void
  ): Promise<void> {
    console.log('[ClaudeClient] Starting stream request')

    const requestBody = JSON.stringify({
      model: this.model,
      max_tokens: this.maxTokens,
      system: systemPrompt,
      messages: [
        {
          role: 'user',
          content: userPrompt,
        },
      ],
      stream: true,
    })

    try {
      const response = await fetch(`${this.baseUrl}/v1/messages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': this.apiKey,
          'anthropic-version': '2023-06-01',
        },
        body: requestBody,
      })

      if (!response.ok) {
        const errorBody = await response.text()
        const errorData = JSON.parse(errorBody || '{}')
        throw new Error(`API error (${response.status}): ${errorData.error?.message || response.statusText}`)
      }

      if (!response.body) {
        throw new Error('No response body')
      }

      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''

      while (true) {
        const { done, value } = await reader.read()

        if (done) {
          break
        }

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6)

            if (data === '[DONE]') {
              return
            }

            try {
              const parsed = JSON.parse(data)

              if (parsed.type === 'content_block_delta') {
                if (parsed.delta?.type === 'text_delta'?.text) {
                  onChunk(parsed.delta.text)
                }
              } else if (parsed.type === 'error') {
                throw new Error(parsed.error?.message || 'Stream error')
              }
            } catch (e) {
              // Ignore parse errors for non-JSON lines
            }
          }
        }
      }
    } catch (error) {
      console.error('[ClaudeClient] Stream error:', error)
      if (error instanceof Error) {
        onError(error)
      } else {
        onError(new Error(String(error)))
      }
    }
  }
}

