import type { CodeContext, ExplainOptions } from '../../types/index';

/**
 * Builds a prompt that instructs Claude to return a GuidedExplanation JSON
 * object. The prompt preserves all context (project metadata, target file,
 * imports, exports, code, related files) and replaces the former free-form
 * text instructions with structured-output requirements keyed to the
 * requested detail level.
 */
export function buildExplainPrompt(context: CodeContext, options: ExplainOptions): string {
  const level = options.level ?? 3;
  const { projectMetadata, targetFile, targetCode, relatedFiles, userQuery } = context;

  // ── Project metadata ───────────────────────────────────────────────
  let prompt = `# 项目背景

请用中文回复。

**项目名称**: ${projectMetadata.name}
**项目类型**: ${projectMetadata.type}
**技术栈**: ${projectMetadata.stack.join(', ')}
**文件总数**: ${projectMetadata.totalFiles}

`;

  // ── Target file ────────────────────────────────────────────────────
  if (targetFile && targetCode) {
    prompt += `# 目标文件

**文件路径**: ${targetFile.path}
**语言**: ${targetFile.language}
**文件大小**: ${targetFile.size} 字节
**代码行数**: ${targetFile.lines}

`;

    if (targetFile.imports.length > 0) {
      prompt += `## 导入

该文件导入了以下模块：
${targetFile.imports.map(imp => `- \`${imp.source}\`${imp.specifiers.length > 0 ? `: ${imp.specifiers.join(', ')}` : ''}`).join('\n')}

`;
    }

    if (targetFile.exports.length > 0) {
      prompt += `## 导出

该文件导出了：
${targetFile.exports.map(exp => `- ${exp.type}: \`${exp.name}\``).join('\n')}

`;
    }

    prompt += `## 完整源代码

\`\`\`${targetFile.language}
${targetCode}
\`\`\`

`;
  }

  // ── Related files ──────────────────────────────────────────────────
  if (relatedFiles && relatedFiles.length > 0) {
    prompt += `# 相关文件

以下是与目标文件相关的文件：

`;
    for (const related of relatedFiles) {
      prompt += `## ${related.path}

`;
      if (related.summary) {
        prompt += `**摘要**: ${related.summary}

`;
      }
      prompt += `\`\`\`
${related.code}
\`\`\`

`;
    }
  }

  // ── Output instructions (structured JSON) ──────────────────────────
  prompt += `# 输出要求

你必须返回一个符合以下 GuidedExplanation 模式的 JSON 对象。
不要返回自由格式的文本、markdown 或 JSON 对象之外的任何内容。
不要在 JSON 周围包裹代码栅栏。

\`\`\`
interface ExplainStep {
  file: string;        // 相对文件路径
  startLine: number;   // 文件内的起始行号（从1开始）
  endLine: number;     // 文件内的结束行号（从1开始）
  title: string;       // 简洁的步骤标题
  content: string;     // 该特定代码部分的解释
  codeSnippet?: string; // 该部分的关键代码行（可选）
}

interface GuidedExplanation {
  overview: string;            // 2-3句话概述
  steps: ExplainStep[];        // 有序的解释步骤
  summary: string;             // 2-3句话总结
  suggestedQuestions: string[]; // 3-5个后续问题
}
\`\`\`

`;

  // ── Level-specific guidance ────────────────────────────────────────
  prompt += buildLevelInstructions(level);

  // ── Line-number accuracy reminder ─────────────────────────────────
  prompt += `
## 行号准确性

- 每个步骤必须引用与上述源代码对应的准确 startLine 和 endLine 值。
- 行号从1开始。
- 每个步骤应尽可能覆盖不同的、不重叠的代码部分。
- 每个步骤中的 file 字段必须是有效的相对文件路径。

`;

  // ── User query ─────────────────────────────────────────────────────
  if (userQuery) {
    prompt += `# 用户问题

用户提出了以下问题：
${userQuery}

Incorporate the answer into the relevant step(s) of your explanation.
If the question relates to a specific code section, ensure there is a dedicated step
that addresses it.
`;
  }

  return prompt;
}

/**
 * 返回级别特定的指令，控制 Claude 应该生成的解释步骤的深度和数量。
 */
function buildLevelInstructions(level: 1 | 2 | 3 | 4): string {
  switch (level) {
    case 1:
      return `## 详细程度：快速概述（第1级）

- 提供简洁的概述（1-2句话）。
- 生成 **2-3个步骤**，仅覆盖最重要的部分：
  - 主要目的 / 入口点
  - 关键导出或公共 API
- 每个步骤的内容应简短（50-100字）。
- 重点说明代码做什么，而不是如何做。
- 总结应为一句话。
- 提供3个后续问题以便深入探索。
`;

    case 2:
      return `## 详细程度：功能摘要（第2级）

- 提供清晰的概述（2-3句话）。
- 生成 **4-6个步骤**，覆盖主要功能区域：
  - 导入和依赖
  - 每个主要导出或公共函数
  - 关键数据结构或类型
- 每个步骤的内容应适中（100-150字）。
- 解释每个部分在更大项目中的作用。
- 总结应将各个部分联系起来（2句话）。
- 提供3-4个后续问题。
`;

    case 3:
      return `## 详细程度：详细解释（第3级）

- 提供全面的概述（2-3句话），包括架构上下文。
- 生成 **6-10个步骤**，覆盖：
  - 导入、依赖以及为什么需要它们
  - 核心逻辑和算法
  - 每个导出的函数、类或模块
  - 与其他模块的交互模式
  - 使用的设计模式和最佳实践
  - 错误处理和边缘情况
- 每个步骤的内容应详细（150-250字）。
- 解释每个部分的"是什么"和"如何做"。
- 总结应突出关键要点和设计决策（2-3句话）。
- 提供4-5个针对架构、性能或改进的后续问题。
`;

    case 4:
      return `## 详细程度：深入分析（第4级）

- 提供全面的概述（3-4句话），包含完整的架构上下文。
- 生成 **10-15个步骤**，覆盖每个重要的代码部分：
  - 每个导入及其目的
  - 每个函数/方法及其参数和返回类型分析
  - 算法和数据结构选择及其理由
  - 控制流和分支逻辑
  - 错误处理、边界条件和边缘情况
  - 类型系统的使用和类型安全考虑
  - 性能影响
  - 与外部系统或 API 的交互
  - 可能的改进或技术债务
- 每个步骤的内容应详尽（200-300字）。
- 解释每个部分的"是什么"、"如何做"和"为什么"。
- 在相关的地方为每个步骤包含 codeSnippet。
- 总结应涵盖设计质量、潜在问题和学习亮点（3-4句话）。
- 提供5个涵盖架构、优化、测试和备选方案的后续问题。
`;
  }
}

import type { ProjectMetadata, FileAnalysis } from '../../types/index';

export function buildLearnPrompt(metadata: ProjectMetadata, fileAnalyses: FileAnalysis[]): string {
  const prompt = `# 项目信息

请用中文回复。

**项目名称**：${metadata.name}
**项目类型**：${metadata.type}
**技术栈**：${metadata.stack.join(', ')}
**总文件数**：${metadata.totalFiles}
**入口文件**：${metadata.entryFiles.join(', ')}

# 文件分析结果

以下是项目中所有文件的分析信息：

${fileAnalyses.map(file => `## ${file.path}

- **语言**：${file.language}
- **大小**：${file.size} 字节
- **行数**：${file.lines} 行
- **导入**：${file.imports.length} 个
- **导出**：${file.exports.length} 个
${file.role ? `- **角色**：${file.role}` : ''}
${file.summary ? `- **简介**：${file.summary}` : ''}
`).join('\n')}

# 任务要求

请基于以上项目信息和文件分析，为开发者设计一个**循序渐进的学习路径**。

## 输出格式

请严格按照以下 JSON 格式输出（不要包含任何其他文字说明）：

\`\`\`json
{
  "phases": [
    {
      "title": "阶段标题",
      "description": "阶段描述，说明这个阶段要学习什么",
      "files": [
        {
          "path": "文件路径",
          "reason": "为什么在这个阶段学习这个文件",
          "completed": false
        }
      ]
    }
  ],
  "generatedAt": "${new Date().toISOString()}"
}
\`\`\`

## 设计原则

1. **从基础到高级**：先学习基础类型、工具函数，再学习核心业务逻辑
2. **从底层到上层**：先学习被依赖的模块，再学习依赖它们的模块
3. **从简单到复杂**：先学习简单的文件，再学习复杂的文件
4. **分阶段组织**：将学习过程分为 3-5 个阶段，每个阶段有明确的学习目标
5. **说明理由**：为每个文件说明为什么要在这个阶段学习它

## 注意事项

- 每个阶段包含 2-5 个文件
- 阶段标题要简洁明了（如"基础类型定义"、"核心工具函数"等）
- 阶段描述要说明学习目标和重点
- 文件的学习理由要具体，说明该文件的作用和学习价值
- 确保输出的是有效的 JSON 格式`;

  return prompt;
}

