import type { CodeContext, ChatMessage } from '../../types/index';

export function buildChatPrompt(context: CodeContext, history: ChatMessage[]): string {
  const { projectMetadata, targetFile, targetCode, relatedFiles } = context;

  let prompt = `# 项目上下文

**项目名称**：${projectMetadata.name}
**项目类型**：${projectMetadata.type}
**技术栈**：${projectMetadata.stack.join(', ')}

`;

  if (targetFile && targetCode) {
    prompt += `# 当前讨论的文件

**文件路径**：${targetFile.path}
**编程语言**：${targetFile.language}

\`\`\`${targetFile.language}
${targetCode}
\`\`\`

`;
  }

  if (relatedFiles && relatedFiles.length > 0) {
    prompt += `# 相关文件

`;
    for (const related of relatedFiles) {
      prompt += `## ${related.path}

\`\`\`
${related.code}
\`\`\`

`;
    }
  }

  if (history.length > 0) {
    prompt += `# 对话历史

`;
    for (const msg of history) {
      const role = msg.role === 'user' ? '用户' : 'CodeGuide';
      prompt += `**${role}**（${msg.timestamp}）：
${msg.content}

`;
    }
  }

  prompt += `# 指示

请基于以上项目上下文和对话历史，回答用户的问题。保持友好、专业的语气，提供准确、有帮助的回答。`;

  return prompt;
}

