import { promises as fs } from 'fs';
import path from 'path';
import type { FileAnalysis, ImportInfo, ExportInfo } from '../../types/index';

export class FileAnalyzer {
  async analyze(filePath: string): Promise<FileAnalysis> {
    const content = await fs.readFile(filePath, 'utf-8');
    const stats = await fs.stat(filePath);
    const language = this.getLanguageFromExt(filePath);
    const lines = content.split('\n').length;
    const imports = this.extractImports(content, language);
    const exports = this.extractExports(content, language);
    const role = this.detectRole(filePath, content);

    return {
      path: filePath,
      language,
      size: stats.size,
      lines,
      imports,
      exports,
      role,
    };
  }

  private extractImports(content: string, language: string): ImportInfo[] {
    const imports: ImportInfo[] = [];

    if (['typescript', 'javascript', 'typescriptreact', 'javascriptreact'].includes(language)) {
      // ES module imports: import { A, B } from 'module'
      const esImportRegex = /import\s+(?:(?:\{([^}]*)\}|\*\s+as\s+(\w+)|(\w+))\s*,?\s*)*(?:\{([^}]*)\})?\s*from\s*['"]([^'"]+)['"]/g;
      let match: RegExpExecArray | null;

      while ((match = esImportRegex.exec(content)) !== null) {
        const specifiers: string[] = [];
        const source = match[5];

        // Collect named imports
        [match[1], match[4]].forEach(group => {
          if (group) {
            group.split(',').map(s => s.trim().split(/\s+as\s+/)[0].trim()).filter(Boolean).forEach(s => specifiers.push(s));
          }
        });
        // Namespace import
        if (match[2]) specifiers.push(`* as ${match[2]}`);
        // Default import
        if (match[3]) specifiers.push(match[3]);

        imports.push({ source, specifiers });
      }

      // Also handle: import 'module' (side-effect imports)
      const sideEffectRegex = /import\s+['"]([^'"]+)['"]/g;
      while ((match = sideEffectRegex.exec(content)) !== null) {
        if (!imports.some(i => i.source === match![1])) {
          imports.push({ source: match![1], specifiers: [] });
        }
      }

      // CommonJS requires: const X = require('module')
      const requireRegex = /(?:const|let|var)\s+(?:\{([^}]*)\}|(\w+))\s*=\s*require\(['"]([^'"]+)['"]\)/g;
      while ((match = requireRegex.exec(content)) !== null) {
        const specifiers: string[] = [];
        if (match[1]) {
          match[1].split(',').map(s => s.trim()).filter(Boolean).forEach(s => specifiers.push(s));
        }
        if (match[2]) specifiers.push(match[2]);
        imports.push({ source: match[3], specifiers });
      }
    }

    if (language === 'python') {
      // Python: from module import A, B
      const fromImportRegex = /from\s+(\S+)\s+import\s+(.+)/g;
      let match;
      while ((match = fromImportRegex.exec(content)) !== null) {
        const specifiers = match[2].split(',').map(s => s.trim().split(/\s+as\s+/)[0].trim()).filter(Boolean);
        imports.push({ source: match[1], specifiers });
      }
      // Python: import module
      const importRegex = /^import\s+(\S+)/gm;
      while ((match = importRegex.exec(content)) !== null) {
        imports.push({ source: match[1], specifiers: [] });
      }
    }

    return imports;
  }

  private extractExports(content: string, language: string): ExportInfo[] {
    const exports: ExportInfo[] = [];

    if (['typescript', 'javascript', 'typescriptreact', 'javascriptreact'].includes(language)) {
      // Named exports: export function/class/const/type/interface
      const namedExportRegex = /export\s+(?:default\s+)?(function|class|const|let|var|type|interface|enum)\s+(\w+)/g;
      let match;
      while ((match = namedExportRegex.exec(content)) !== null) {
        exports.push({ name: match[2], type: match[1] });
      }

      // Re-exports: export { A, B } from 'module'
      const reExportRegex = /export\s+\{([^}]*)\}\s*from\s*['"][^'"]+['"]/g;
      while ((match = reExportRegex.exec(content)) !== null) {
        match[1].split(',').map(s => s.trim().split(/\s+as\s+/).pop()!.trim()).filter(Boolean).forEach(name => {
          exports.push({ name, type: 're-export' });
        });
      }

      // Default export: export default
      if (/export\s+default\s+/.test(content) && !exports.some(e => e.name === 'default')) {
        exports.push({ name: 'default', type: 'default' });
      }
    }

    return exports;
  }

  private detectRole(filePath: string, content: string): string | undefined {
    const fileName = path.basename(filePath).toLowerCase();
    const dirName = path.dirname(filePath).toLowerCase();

    // Config files
    if (fileName.match(/\.(config|rc|settings)\.(ts|js|json|yaml|yml)$/) || fileName.startsWith('.')) {
      return 'config';
    }

    // Test files
    if (fileName.match(/\.(test|spec|e2e)\.(ts|js|tsx|jsx)$/) || dirName.includes('__tests__') || dirName.includes('test')) {
      return 'test';
    }

    // Entry point
    if (fileName.match(/^(index|main|app)\.(ts|js|tsx|jsx)$/)) {
      return 'entry';
    }

    // Route files
    if (dirName.includes('route') || dirName.includes('page') || fileName.includes('route') || fileName.includes('router')) {
      return 'route';
    }

    // Components
    if (dirName.includes('component') || (content.includes('React') && /export\s+(default\s+)?function\s+[A-Z]/.test(content))) {
      return 'component';
    }

    // Service/API files
    if (dirName.includes('service') || dirName.includes('api') || fileName.includes('service') || fileName.includes('api')) {
      return 'service';
    }

    // State management
    if (dirName.includes('store') || dirName.includes('state') || fileName.includes('store') || fileName.includes('reducer')) {
      return 'state';
    }

    // Utility files
    if (dirName.includes('util') || dirName.includes('helper') || dirName.includes('lib') || fileName.includes('util') || fileName.includes('helper')) {
      return 'utility';
    }

    // Type definitions
    if (fileName.match(/types?\.(ts|d\.ts)$/) || dirName.includes('types')) {
      return 'model';
    }

    // Middleware
    if (dirName.includes('middleware') || fileName.includes('middleware')) {
      return 'middleware';
    }

    return undefined;
  }

  private getLanguageFromExt(filePath: string): string {
    const ext = path.extname(filePath).toLowerCase();
    const langMap: Record<string, string> = {
      '.ts': 'typescript',
      '.tsx': 'typescriptreact',
      '.js': 'javascript',
      '.jsx': 'javascriptreact',
      '.py': 'python',
      '.go': 'go',
      '.rs': 'rust',
      '.java': 'java',
      '.rb': 'ruby',
      '.php': 'php',
      '.css': 'css',
      '.scss': 'scss',
      '.html': 'html',
      '.vue': 'vue',
      '.svelte': 'svelte',
      '.json': 'json',
      '.yaml': 'yaml',
      '.yml': 'yaml',
      '.md': 'markdown',
      '.sql': 'sql',
      '.sh': 'shell',
      '.c': 'c',
      '.cpp': 'cpp',
      '.h': 'c',
      '.hpp': 'cpp',
    };
    return langMap[ext] || 'plaintext';
  }
}

