// Project metadata from scanning
export interface ProjectMetadata {
  name: string;
  type: string; // e.g., "react", "node", "vue", "python"
  stack: string[]; // e.g., ["React 18", "TypeScript", "Redux"]
  entryFiles: string[];
  totalFiles: number;
  directoryTree?: DirectoryNode;
}

export interface DirectoryNode {
  name: string;
  path: string;
  type: 'file' | 'directory';
  children?: DirectoryNode[];
  role?: string;
}

export interface FileAnalysis {
  path: string;
  language: string;
  imports: ImportInfo[];
  exports: ExportInfo[];
  summary?: string;
  role?: string;
  size: number;
  lines: number;
}

export interface ImportInfo {
  source: string;
  specifiers: string[];
}

export interface ExportInfo {
  name: string;
  type: string;
}

// Context for AI
export interface CodeContext {
  projectMetadata: ProjectMetadata;
  targetFile?: FileAnalysis;
  targetCode?: string;
  relatedFiles?: { path: string; code: string; summary?: string }[];
  userQuery?: string;
}

// Learning path
export interface LearningPath {
  phases: LearningPhase[];
  generatedAt: string;
}

export interface LearningPhase {
  title: string;
  description: string;
  files: LearningFile[];
}

export interface LearningFile {
  path: string;
  reason: string;
  completed: boolean;
}

// Session
export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
}

export interface Session {
  id: string;
  projectPath: string;
  messages: ChatMessage[];
  createdAt: string;
  updatedAt: string;
}

// Config
export interface CodeGuideConfig {
  anthropicApiKey?: string;
  model?: string;
  language?: string;
  maxTokens?: number;
}

// Explain options
export interface ExplainOptions {
  level?: 1 | 2 | 3 | 4;
  interactive?: boolean;
}

// ============================================
// VS Code Extension types (guided explanation)
// ============================================

// A single step in the guided explanation
export interface ExplainStep {
  file: string;        // relative file path
  startLine: number;   // 1-indexed highlight start line
  endLine: number;     // 1-indexed highlight end line
  title: string;       // step title
  content: string;     // Markdown explanation content
  codeSnippet?: string; // key code snippet
}

// Complete guided explanation result from AI
export interface GuidedExplanation {
  overview: string;            // file/project overview
  steps: ExplainStep[];        // step-by-step explanation
  summary: string;             // final summary
  suggestedQuestions: string[]; // suggested follow-up questions
}

// Guide session state
export interface GuideSessionState {
  projectMetadata: ProjectMetadata;
  learningPath: LearningPath;
  currentPhaseIndex: number;
  currentFileIndex: number;
  currentStepIndex: number;
  currentExplanation?: GuidedExplanation;
  chatHistory: ChatMessage[];
  isActive: boolean;
}

// Messages between Webview and Extension
export type WebviewMessage =
  | { type: 'startGuide' }
  | { type: 'nextStep' }
  | { type: 'previousStep' }
  | { type: 'askQuestion'; question: string }
  | { type: 'skipFile' }
  | { type: 'stopGuide' }
  | { type: 'selectPhase'; phaseIndex: number }
  | { type: 'selectFile'; phaseIndex: number; fileIndex: number }
  | { type: 'ready' };

export type ExtensionMessage =
  | { type: 'showStep'; step: ExplainStep; stepIndex: number; totalSteps: number; fileProgress: string; phaseProgress: string }
  | { type: 'showOverview'; overview: string; projectName: string }
  | { type: 'showAnswer'; answer: string }
  | { type: 'showLoading'; message: string }
  | { type: 'showError'; error: string }
  | { type: 'guideStarted'; learningPath: LearningPath }
  | { type: 'guideStopped' }
  | { type: 'updateProgress'; currentPhase: number; totalPhases: number; currentFile: number; totalFiles: number }
  | { type: 'workflowLog'; level: 'info' | 'ai' | 'success' | 'error'; message: string; timestamp: string };

