import type { ProjectMetadata, FileAnalysis } from '../../types/index';

export function buildLearnPrompt(metadata: ProjectMetadata, fileAnalyses: FileAnalysis[]): string {
  const prompt = `# 项目信息

请用中文回复。

**项目名称**：${metadata.name}
**项目类型**：${metadata.type}
**技术栈**：${metadata.stack.join(', ')}
**总文件数**：${metadata.totalFiles}
**入口文件**：${metadata.entryFiles.join(', ')}

# 文件分析结果

以下是项目中所有文件的分析信息：

${fileAnalyses.map(file => `## ${file.path}

- **语言**：${file.language}
- **大小**：${file.size} 字节
- **行数**：${file.lines} 行
- **导入**：${file.imports.length} 个
- **导出**：${file.exports.length} 个
${file.role ? `- **角色**：${file.role}` : ''}
${file.summary ? `- **简介**：${file.summary}` : ''}
`).join('\n')}

# 任务要求

请基于以上项目信息和文件分析，为开发者设计一个**循序渐进的学习路径**。

## 输出格式

请严格按照以下 JSON 格式输出（不要包含任何其他文字说明）：

\`\`\`json
{
  "phases": [
    {
      "title": "阶段标题",
      "description": "阶段描述，说明这个阶段要学习什么",
      "files": [
        {
          "path": "文件路径",
          "reason": "为什么在这个阶段学习这个文件",
          "completed": false
        }
      ]
    }
  ],
  "generatedAt": "${new Date().toISOString()}"
}
\`\`\`

## 设计原则

1. **从基础到高级**：先学习基础类型、工具函数，再学习核心业务逻辑
2. **从底层到上层**：先学习被依赖的模块，再学习依赖它们的模块
3. **从简单到复杂**：先学习简单的文件，再学习复杂的文件
4. **分阶段组织**：将学习过程分为 3-5 个阶段，每个阶段有明确的学习目标
5. **说明理由**：为每个文件说明为什么要在这个阶段学习它

## 注意事项

- 每个阶段包含 2-5 个文件
- 阶段标题要简洁明了（如"基础类型定义"、"核心工具函数"等）
- 阶段描述要说明学习目标和重点
- 文件的学习理由要具体，说明该文件的作用和学习价值
- 确保输出的是有效的 JSON 格式`;

  return prompt;
}

