import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

export interface ClaudeCodeConfig {
  apiKey?: string;
  baseUrl?: string;
  model?: string;
  haikuModel?: string;
  sonnetModel?: string;
  opusModel?: string;
}

/**
 * Read Claude Code configuration from ~/.claude/settings.json
 */
export async function readClaudeCodeConfig(): Promise<ClaudeCodeConfig | null> {
  try {
    const configPath = path.join(os.homedir(), '.claude', 'settings.json');

    if (!fs.existsSync(configPath)) {
      return null;
    }

    const content = await fs.promises.readFile(configPath, 'utf-8');
    const config = JSON.parse(content);

    if (!config.env) {
      return null;
    }

    return {
      apiKey: config.env.ANTHROPIC_AUTH_TOKEN,
      baseUrl: config.env.ANTHROPIC_BASE_URL,
      model: config.env.ANTHROPIC_MODEL,
      haikuModel: config.env.ANTHROPIC_DEFAULT_HAIKU_MODEL,
      sonnetModel: config.env.ANTHROPIC_DEFAULT_SONNET_MODEL,
      opusModel: config.env.ANTHROPIC_DEFAULT_OPUS_MODEL,
    };
  } catch (error) {
    console.error('Failed to read Claude Code config:', error);
    return null;
  }
}

/**
 * Read config (sync version for simpler use cases)
 */
export function readConfig(): ClaudeCodeConfig {
  try {
    const configPath = path.join(os.homedir(), '.claude', 'settings.json');

    if (!fs.existsSync(configPath)) {
      return {};
    }

    const content = fs.readFileSync(configPath, 'utf-8');
    const config = JSON.parse(content);

    if (!config.env) {
      return {};
    }

    return {
      apiKey: config.env.ANTHROPIC_AUTH_TOKEN,
      baseUrl: config.env.ANTHROPIC_BASE_URL,
      model: config.env.ANTHROPIC_MODEL,
      haikuModel: config.env.ANTHROPIC_DEFAULT_HAIKU_MODEL,
      sonnetModel: config.env.ANTHROPIC_DEFAULT_SONNET_MODEL,
      opusModel: config.env.ANTHROPIC_DEFAULT_OPUS_MODEL,
    };
  } catch (error) {
    console.error('Failed to read config:', error);
    return {};
  }
}

/**
 * Get effective API configuration
 */
export function getEffectiveConfig(appConfig?: {
  apiKey?: string;
  baseUrl?: string;
  model?: string;
}): ClaudeCodeConfig {
  const claudeCodeConfig = readConfig();

  return {
    apiKey: appConfig?.apiKey || claudeCodeConfig?.apiKey,
    baseUrl: appConfig?.baseUrl || claudeCodeConfig?.baseUrl || 'https://api.anthropic.com',
    model: appConfig?.model || claudeCodeConfig?.model || 'claude-sonnet-4-20250514',
    haikuModel: claudeCodeConfig?.haikuModel,
    sonnetModel: claudeCodeConfig?.sonnetModel,
    opusModel: claudeCodeConfig?.opusModel,
  };
}

