import { useGuideStore } from '../../stores/guideStore';

export function LearningPathTree() {
  const { learningPath, currentPhaseIndex, currentFileIndex, isActive, goToStep } = useGuideStore();

  if (!isActive || !learningPath) {
    return (
      <div className="p-4 text-sm text-gray-500">
        <p>点击"开始学习"按钮启动引导</p>
      </div>
    );
  }

  return (
    <div className="p-2">
      <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 px-2">
        学习路径
      </h3>
      {learningPath.phases.map((phase, phaseIndex) => (
        <div key={phaseIndex} className="mb-2">
          <div
            className={`px-2 py-1 text-sm font-medium rounded ${
              phaseIndex === currentPhaseIndex
                ? 'bg-primary-100 dark:bg-primary-900 text-primary-700 dark:text-primary-300'
                : 'text-gray-600 dark:text-gray-400'
            }`}
          >
            {phase.title}
          </div>
          <div className="ml-4 mt-1 space-y-1">
            {phase.files.map((file, fileIndex) => (
              <button
                key={fileIndex}
                onClick={() => goToStep(phaseIndex, fileIndex, 0)}
                className={`w-full text-left px-2 py-1 text-sm rounded truncate ${
                  phaseIndex === currentPhaseIndex && fileIndex === currentFileIndex
                    ? 'bg-primary-50 dark:bg-primary-900/50 text-primary-600 dark:text-primary-400'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800'
                }`}
              >
                {file.path.split('/').pop()}
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

