import { useGuideStore } from '../../stores/guideStore';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

export function ExplanationPanel() {
  const { currentStep, currentExplanation, isLoading, loadingMessage } = useGuideStore();

  if (isLoading) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin w-8 h-8 border-2 border-primary-500 border-t-transparent rounded-full mx-auto mb-2"></div>
          <p className="text-sm text-gray-500">{loadingMessage || '加载中...'}</p>
        </div>
      </div>
    );
  }

  if (!currentStep && !currentExplanation) {
    return (
      <div className="h-full flex items-center justify-center">
        <p className="text-gray-500">点击"下一步"开始学习</p>
      </div>
    );
  }

  return (
    <div className="h-full overflow-y-auto p-4">
      {currentStep && (
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className="px-2 py-0.5 text-xs font-medium bg-primary-100 dark:bg-primary-900 text-primary-700 dark:text-primary-300 rounded">
              步骤 {currentStep.title}
            </span>
          </div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-3">
            {currentStep.title}
          </h3>
          <div className="prose prose-sm dark:prose-invert max-w-none">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
              {currentStep.content}
            </ReactMarkdown>
          </div>
          {currentStep.codeSnippet && (
            <pre className="mt-4 p-3 bg-gray-100 dark:bg-slate-800 rounded-lg overflow-x-auto">
              <code className="text-sm">{currentStep.codeSnippet}</code>
            </pre>
          )}
        </div>
      )}

      {currentExplanation && (
        <div className="mt-6 pt-4 border-t border-gray-200 dark:border-slate-700">
          <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            推荐问题
          </h4>
          <ul className="space-y-1">
            {currentExplanation.suggestedQuestions.map((q, i) => (
              <li key={i} className="text-sm text-gray-500 dark:text-gray-400">
                • {q}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

