import { useGuideStore } from '../../stores/guideStore';
import { useState } from 'react';

export function ChatPanel() {
  const { chatHistory, chatInput, isChatLoading, setChatInput, addChatMessage, setChatLoading } = useGuideStore();
  const [streamedAnswer, setStreamedAnswer] = useState('');

  const handleSend = async () => {
    if (!chatInput.trim() || isChatLoading) return;

    const question = chatInput;
    setChatInput('');
    setChatLoading(true);
    setStreamedAnswer('');

    // Add user message
    addChatMessage({
      role: 'user',
      content: question,
      timestamp: new Date().toISOString(),
    });

    // Add empty assistant message for streaming
    addChatMessage({
      role: 'assistant',
      content: '',
      timestamp: new Date().toISOString(),
    });

    try {
      if (window.electronAPI) {
        // Use streaming
        await window.electronAPI.ai.stream(
          '你是一位专业的代码导师，请用中文回答用户的问题。',
          question
        );

        // Listen for chunks
        const unsubscribe = window.electronAPI.on('ai:streamChunk', (chunk: string) => {
          setStreamedAnswer((prev) => prev + chunk);
        });

        // Wait for done
        window.electronAPI.on('ai:streamDone', () => {
          unsubscribe();
          // Update the last message
          const state = useGuideStore.getState();
          const messages = [...state.chatHistory];
          messages[messages.length - 1].content = streamedAnswer || state.chatHistory[state.chatHistory.length - 1].content;
          useGuideStore.setState({ chatHistory: messages, isChatLoading: false });
        });
      }
    } catch (error) {
      console.error('Chat error:', error);
      setChatLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col">
      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {chatHistory.map((msg, i) => (
          <div key={i} className={`${msg.role === 'user' ? 'ml-8' : 'mr-8'}`}>
            <div
              className={`px-3 py-2 rounded-lg ${
                msg.role === 'user'
                  ? 'bg-primary-500 text-white'
                  : 'bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-gray-100'
              }`}
            >
              <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
            </div>
            <p className="text-xs text-gray-400 mt-1">
              {new Date(msg.timestamp).toLocaleTimeString()}
            </p>
          </div>
        ))}
        {streamedAnswer && (
          <div className="mr-8">
            <div className="bg-gray-100 dark:bg-slate-800 px-3 py-2 rounded-lg">
              <p className="text-sm whitespace-pre-wrap">{streamedAnswer}</p>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-3 border-t border-gray-200 dark:border-slate-700">
        <div className="flex gap-2">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="向 AI 提问..."
            className="flex-1 px-3 py-2 text-sm border border-gray-300 dark:border-slate-600 rounded-md bg-white dark:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-primary-500"
            disabled={isChatLoading}
          />
          <button
            onClick={handleSend}
            disabled={isChatLoading || !chatInput.trim()}
            className="px-4 py-2 text-sm bg-primary-500 text-white rounded-md hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isChatLoading ? '...' : '发送'}
          </button>
        </div>
      </div>
    </div>
  );
}

