import Store from 'electron-store';
import log from 'electron-log';

interface SessionData {
  projectId: string;
  stateJson: string;
  updatedAt: string;
}

interface AnnotationData {
  id: number;
  projectId: string;
  filePath: string;
  startLine: number;
  endLine: number;
  content: string;
  type: string;
  tagsJson: string;
  createdAt: string;
}

interface StoreSchema {
  sessions: Record<string, SessionData>;
  annotations: Record<string, AnnotationData[]>;
}

let store: Store<StoreSchema> | null = null;

export function getStore(): Store<StoreSchema> {
  if (!store) {
    store = new Store<StoreSchema>({
      name: 'readcode-data',
      defaults: {
        sessions: {},
        annotations: {},
      },
    });
  }
  return store;
}

export async function initDatabase(): Promise<void> {
  // Using electron-store instead of SQLite
  getStore();
  log.info('Data store initialized');
}

export function saveSession(projectId: string, state: any): void {
  const store = getStore();
  const sessions = store.get('sessions', {});
  sessions[projectId] = {
    projectId,
    stateJson: JSON.stringify(state),
    updatedAt: new Date().toISOString(),
  };
  store.set('sessions', sessions);
}

export function loadSession(projectId: string): any | null {
  const store = getStore();
  const sessions = store.get('sessions', {});
  const session = sessions[projectId];
  if (session) {
    return JSON.parse(session.stateJson);
  }
  return null;
}

export function saveAnnotations(projectId: string, annotations: any[]): void {
  const store = getStore();
  const allAnnotations = store.get('annotations', {});
  allAnnotations[projectId] = annotations.map((a, i) => ({
    id: i,
    projectId,
    filePath: a.filePath,
    startLine: a.startLine,
    endLine: a.endLine,
    content: a.content,
    type: a.type || 'note',
    tagsJson: JSON.stringify(a.tags || []),
    createdAt: new Date().toISOString(),
  }));
  store.set('annotations', allAnnotations);
}

export function loadAnnotations(projectId: string): any[] {
  const store = getStore();
  const allAnnotations = store.get('annotations', {});
  return allAnnotations[projectId] || [];
}

