import { ipcMain } from 'electron'
import { getDatabase } from '../services/database'
import log from 'electron-log'

export function registerStoreHandlers(): void {
  // Save session
  ipcMain.handle('store:saveSession', async (_event, projectId: string, state: any) => {
    try {
      const db = getDatabase()
      const stmt = db.prepare(`
        INSERT OR REPLACE INTO sessions (project_id, state_json, updated_at)
        VALUES (?, ?, datetime('now'))
      `)
      stmt.run(projectId, JSON.stringify(state))
    } catch (error) {
      log.error('Save session error:', error)
      throw error
    }
  })

  // Load session
  ipcMain.handle('store:loadSession', async (_event, projectId: string) => {
    try {
      const db = getDatabase()
      const stmt = db.prepare('SELECT state_json FROM sessions WHERE project_id = ?')
      const row = stmt.get(projectId) as { state_json: string } | undefined
      if (row) {
        return JSON.parse(row.state_json)
      }
      return null
    } catch (error) {
      log.error('Load session error:', error)
      throw error
    }
  })

  // Save annotations
  ipcMain.handle('store:saveAnnotations', async (_event, projectId: string, annotations: any[]) => {
    try {
      const db = getDatabase()

      // Delete existing annotations for this project
      const deleteStmt = db.prepare('DELETE FROM annotations WHERE project_id = ?')
      deleteStmt.run(projectId)

      // Insert new annotations
      const insertStmt = db.prepare(`
        INSERT INTO annotations (project_id, file_path, start_line, end_line, content, type, tags_json, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
      `)

      for (const annotation of annotations) {
        insertStmt.run(
          projectId,
          annotation.filePath,
          annotation.startLine,
          annotation.endLine,
          annotation.content,
          annotation.type,
          JSON.stringify(annotation.tags || [])
        )
      }
    } catch (error) {
      log.error('Save annotations error:', error)
      throw error
    }
  })

  // Load annotations
  ipcMain.handle('store:loadAnnotations', async (_event, projectId: string) => {
    try {
      const db = getDatabase()
      const stmt = db.prepare('SELECT * FROM annotations WHERE project_id = ?')
      const rows = stmt.all(projectId) as any[]
      return rows.map((row) => ({
        id: row.id,
        filePath: row.file_path,
        startLine: row.start_line,
        endLine: row.end_line,
        content: row.content,
        type: row.type,
        tags: JSON.parse(row.tags_json || '[]'),
        createdAt: row.created_at
      }))
    } catch (error) {
      log.error('Load annotations error:', error)
      throw error
    }
  })
}

