   350→  public async executeStep(index: number): Promise<void> {
   351→    try {
   352→      if (!this._state.currentExplanation) {
   353→        throw new Error('No explanation available');
   354→      }
   355→
   356→      const steps = this._state.currentExplanation.steps;
   357→      if (index < 0 || index >= steps.length) {
   358→        throw new Error('Invalid step index');
   359→      }
   360→
   361→      const step = steps[index];
   362→      this._state.currentStepIndex = index;
   363→
   364→      // Resolve file path
   365→      const filePath = this._projectRoot
   366→        ? resolveFilePath(step.file, this._projectRoot)
   367→        : step.file;
   368→
   369→      // Log the line numbers for debugging
   370→      console.log(`[CodeGuide] Step ${index + 1}: ${step.title}`);
   371→      console.log(`[CodeGuide] Line numbers: ${step.startLine} - ${step.endLine}`);
   372→
   373→      // Validate line numbers
   374→      let validStartLine = step.startLine;
   375→      let validEndLine = step.endLine;
   376→
   377→      // Ensure line numbers are positive
   378→      if (validStartLine < 1) {
   379→        console.error(`[CodeGuide] Invalid startLine ${step.startLine}, defaulting to 1`);
   380→        validStartLine = 1;
   381→      }
   382→      if (validEndLine < validStartLine) {
   383→        console.error(`[CodeGuide] Invalid endLine ${step.endLine}, setting to startLine`);
   384→        validEndLine = validStartLine;
   385→      }
   386→
   387→      // Navigate to file and line
   388→      await this._codeNavigator.navigateTo(filePath, validStartLine);
   389→
   390→      // Highlight code range
   391→      this._codeHighlighter.highlight(filePath, validStartLine, validEndLine);
   392→
   393→      // Build progress info
   394→      const currentPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
