   598→  private parseJsonResponse<T>(text: string): T {
   599→    try {
   600→      // Try to extract JSON from markdown code blocks
   601→      const jsonMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
   602→      if (jsonMatch) {
   603→        return JSON.parse(jsonMatch[1].trim());
   604→      }
   605→
   606→      // Try to parse directly
   607→      return JSON.parse(text.trim());
   608→    } catch (e) {
   609→      // Try to fix incomplete JSON by finding the last complete object
   610→      const trimmed = text.trim();
   611→      console.error('[ClaudeClient] JSON parse error, trying to fix...');
   612→
   613→      // Try to find and fix incomplete JSON
   614→      const fixed = this.fixIncompleteJson(trimmed);
   615→      if (fixed) {
   616→        console.error('[ClaudeClient] Successfully fixed JSON');
   617→        return JSON.parse(fixed);
   618→      }
   619→
   620→      throw new Error(`Failed to parse JSON response from AI: ${e instanceof Error ? e.message : 'Unknown error'}`);
   621→    }
   622→  }
   623→
   624→  /**
   625→   * Try to fix incomplete JSON by finding the last complete object
   626→   */
   627→  private fixIncompleteJson(text: string): string | null {
   628→    // Try to find the closing bracket of the main object
   629→    let depth = 0;
   630→    let lastCompletePos = -1;
   631→
   632→    for (let i = 0; i < text.length; i++) {
   633→      if (text[i] === '{') depth++;
   634→      if (text[i] === '}') depth--;
   635→
   636→      if (depth === 0 && text[i] === '}') {
   637→        lastCompletePos = i + 1;
   638→      }
   639→    }
   640→
   641→    if (lastCompletePos > 0) {
   642→      const result = text.substring(0, lastCompletePos);
   643→      // Verify it's valid JSON
   644→      try {
   645→        JSON.parse(result);
   646→        return result;
   647→      } catch {
   648→        return null;
   649→      }
   650→    }
   651→
   652→    return null;
   653→  }
   654→
   655→  /**
   656→   * Format JSON response from AI into readable markdown
   657→   */
   658→  private formatJsonResponse(response: string): string {
   659→    const trimmed = response.trim();
   660→
   661→    // Try to find JSON in the response (might be wrapped in code blocks)
   662→    let jsonMatch = trimmed.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
   663→    let jsonStr = jsonMatch ? jsonMatch[1].trim() : trimmed;
   664→
   665→    try {
   666→      const data = JSON.parse(jsonStr);
   667→
   668→      // Check if it's a Q&A format with overview, steps, summary
   669→      if (data.overview || data.summary || data.steps) {
   670→        let markdown = '';
   671→
   672→        if (data.overview) {
   673→          markdown += `**概述**\n\n${data.overview}\n\n`;
   674→        }
   675→
   676→        if (data.steps && Array.isArray(data.steps)) {
   677→          data.steps.forEach((step: any, index: number) => {
   678→            if (step.title) {
   679→              markdown += `### ${index + 1}. ${step.title}\n\n`;
   680→            }
   681→            if (step.content) {
   682→              markdown += `${step.content}\n\n`;
   683→            }
   684→          });
   685→        }
   686→
   687→        if (data.summary) {
   688→          markdown += `---\n\n**总结**\n\n${data.summary}`;
   689→        }
   690→
   691→        return markdown || response;
   692→      }
   693→
   694→      // Check if it's a simple Q&A with answer field
   695→      if (data.answer) {
   696→        return data.answer;
   697→      }
   698→
   699→      // Check for other common fields
   700→      if (data.response) {
   701→        return data.response;
   702→      }
   703→
   704→      // If JSON but no recognized format, try to stringify nicely
