import * as vscode from 'vscode';
import * as path from 'path';
import { ClaudeClient } from '../ai/ClaudeClient';
import type { AIClientConfig } from '../ai/ClaudeClient';
import { ProjectScanner } from '../core/scanner/ProjectScanner';
import { FileAnalyzer } from '../core/scanner/FileAnalyzer';
import { buildSystemPrompt } from '../ai/prompts/system';
import { buildExplainPrompt } from '../ai/prompts/explain';
import { buildLearnPrompt } from '../ai/prompts/learn';
import { buildChatPrompt } from '../ai/prompts/chat';
import { CodeHighlighter } from './editor/CodeHighlighter';
import { CodeNavigator } from './editor/CodeNavigator';
import { WorkflowLogger } from './WorkflowLogger';
import { readClaudeCodeConfig } from '../utils/configReader';
import type {
  GuideSessionState,
  LearningPath,
  GuidedExplanation,
  ChatMessage,
  ExtensionMessage,
  FileAnalysis,
  CodeContext,
  ExplainOptions
} from '../types/index';

/**
 * Resolve a file path that might be absolute or relative.
 * If it's already absolute, return it as-is.
 * If it's relative, join with projectRoot.
 */
function resolveFilePath(filePath: string, projectRoot: string): string {
  if (path.isAbsolute(filePath)) {
    return filePath;
  }
  return path.join(projectRoot, filePath);
}

export class GuideSession {
  private _context: vscode.ExtensionContext;
  private _state: GuideSessionState;
  private _claudeClient: ClaudeClient | undefined;
  private _projectScanner: ProjectScanner | undefined;
  private _fileAnalyzer: FileAnalyzer | undefined;
  private _codeHighlighter: CodeHighlighter;
  private _codeNavigator: CodeNavigator;
  private _sidebarView: vscode.WebviewView | undefined;
  private _onDidChangeState: vscode.EventEmitter<void>;
  private _projectRoot: string | undefined;
  private _logger: WorkflowLogger;

  constructor(context: vscode.ExtensionContext, logger: WorkflowLogger) {
    this._context = context;
    this._logger = logger;
    this._codeHighlighter = new CodeHighlighter();
    this._codeNavigator = new CodeNavigator();
    this._onDidChangeState = new vscode.EventEmitter<void>();

    this._state = {
      projectMetadata: { name: '', type: '', stack: [], entryFiles: [], totalFiles: 0 },
      learningPath: { phases: [], generatedAt: '' },
      currentPhaseIndex: 0,
      currentFileIndex: 0,
      currentStepIndex: 0,
      chatHistory: [],
      isActive: false
    };
  }

  public getState(): GuideSessionState {
    return this._state;
  }

  public get onDidChangeState(): vscode.Event<void> {
    return this._onDidChangeState.event;
  }

  public setSidebarView(view: vscode.WebviewView): void {
    this._sidebarView = view;
  }

  public async startGuide(projectRoot: string): Promise<void> {
    try {
      this._projectRoot = projectRoot;

      // 设置 logger 的 webview
      if (this._sidebarView) {
        this._logger.setWebview(this._sidebarView.webview);
      }

      this._logger.info('开始引导学习');

      const config = vscode.workspace.getConfiguration('codeguide');
      const configSource = config.get<string>('configSource') || 'claude-code';

      let aiConfig: AIClientConfig;

      if (configSource === 'claude-code') {
        // Read from Claude Code config
        const claudeCodeConfig = await readClaudeCodeConfig();

        if (!claudeCodeConfig || !claudeCodeConfig.apiKey) {
          const choice = await vscode.window.showErrorMessage(
            'Claude Code configuration not found. Would you like to configure manually?',
            'Configure Manually',
            'Cancel'
          );

          if (choice === 'Configure Manually') {
            await vscode.commands.executeCommand('workbench.action.openSettings', 'codeguide.configSource');
          }
          return;
        }

        aiConfig = {
          apiKey: claudeCodeConfig.apiKey,
          baseUrl: claudeCodeConfig.baseUrl,
          model: claudeCodeConfig.model,
          maxTokens: config.get<number>('maxTokens') || 4096
        };

        vscode.window.showInformationMessage(
          `Using Claude Code config: ${claudeCodeConfig.model || 'default model'} @ ${claudeCodeConfig.baseUrl || 'default URL'}`
        );
      } else {
        // Manual configuration
        const apiKey = config.get<string>('apiKey');

        if (!apiKey) {
          const input = await vscode.window.showInputBox({
            prompt: 'Enter your API key',
            password: true,
            placeHolder: 'sk-...',
          });

          if (input) {
            await config.update('apiKey', input, true);
            aiConfig = {
              apiKey: input,
              baseUrl: config.get<string>('baseUrl') || undefined,
              model: config.get<string>('model') || undefined,
              maxTokens: config.get<number>('maxTokens') || 4096
            };
          } else {
            return;
          }
        } else {
          aiConfig = {
            apiKey,
            baseUrl: config.get<string>('baseUrl') || undefined,
            model: config.get<string>('model') || undefined,
            maxTokens: config.get<number>('maxTokens') || 4096
          };
        }
      }

      this._claudeClient = new ClaudeClient(aiConfig);
      this._projectScanner = new ProjectScanner(projectRoot);
      this._fileAnalyzer = new FileAnalyzer();

      this.postMessage({ type: 'showLoading', message: 'Scanning project...' });
      this._logger.info('正在扫描项目结构...');

      await vscode.window.withProgress({
        location: vscode.ProgressLocation.Notification,
        title: 'CodeGuide: Analyzing project...',
        cancellable: false
      }, async (progress) => {
        // Scan project
        progress.report({ message: 'Scanning project structure...' });
        const metadata = await this._projectScanner!.scan();
        this._state.projectMetadata = metadata;
        this._logger.info(`扫描完成：项目 "${metadata.name}"，类型：${metadata.type}，共 ${metadata.totalFiles} 个文件`);

        // Analyze key files
        progress.report({ message: 'Analyzing key files...' });
        const filesToAnalyze = [...metadata.entryFiles].slice(0, 15);
        const fileAnalyses: FileAnalysis[] = [];

        for (const file of filesToAnalyze) {
          try {
            const fullPath = require('path').join(projectRoot, file);
            const analysis = await this._fileAnalyzer!.analyze(fullPath);
            fileAnalyses.push(analysis);
          } catch {
            // Skip files that can't be analyzed
          }
        }

        // Generate learning path
        progress.report({ message: 'Generating learning path...' });
        this.postMessage({ type: 'showLoading', message: 'AI is generating your learning path...' });
        this._logger.ai('正在请求 AI 生成学习路径...');

        const systemPrompt = buildSystemPrompt();
        const learnPrompt = buildLearnPrompt(metadata, fileAnalyses);
        const response = await this._claudeClient!.complete(systemPrompt, learnPrompt);

        const learningPath = this.parseJsonResponse<LearningPath>(response);
        learningPath.generatedAt = new Date().toISOString();
        this._state.learningPath = learningPath;
        this._logger.success(`AI 已生成学习路径（${learningPath.phases.length} 个阶段）`);
      });

      // Activate session
      this._state.isActive = true;
      this._state.currentPhaseIndex = 0;
      this._state.currentFileIndex = 0;
      this._state.currentStepIndex = 0;
      this._onDidChangeState.fire();

      // Notify webview
      this.postMessage({
        type: 'guideStarted',
        learningPath: this._state.learningPath
      });

      this.postMessage({
        type: 'showOverview',
        overview: `Project: ${this._state.projectMetadata.name}\nType: ${this._state.projectMetadata.type}\nStack: ${this._state.projectMetadata.stack.join(', ')}\nFiles: ${this._state.projectMetadata.totalFiles}\nLearning phases: ${this._state.learningPath.phases.length}`,
        projectName: this._state.projectMetadata.name
      });

      // Begin first file explanation
      const firstFile = this._state.learningPath.phases[0]?.files[0];
      if (firstFile) {
        // Add delay between API calls to avoid connection issues
        await new Promise(resolve => setTimeout(resolve, 2000));

        const fullPath = resolveFilePath(firstFile.path, this._projectRoot!);
        await this.explainFile(fullPath);
      }

    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error';
      vscode.window.showErrorMessage(`Failed to start guide: ${msg}`);
      this.postMessage({ type: 'showError', error: msg });
      this._state.isActive = false;
      this._onDidChangeState.fire();
    }
  }

  public async explainFile(filePath: string): Promise<void> {
    try {
      if (!this._claudeClient || !this._fileAnalyzer || !this._projectRoot) {
        throw new Error('Guide session not initialized. Run Start Guide first.');
      }

      const fileName = filePath.split('/').pop() || filePath;
      this.postMessage({ type: 'showLoading', message: 'Analyzing file...' });
      this._logger.info(`正在分析文件: ${fileName}`);

      await vscode.window.withProgress({
        location: vscode.ProgressLocation.Notification,
        title: 'CodeGuide: Generating explanation...',
        cancellable: false
      }, async () => {
        const analysis = await this._fileAnalyzer!.analyze(filePath);

        // Read file content
        const fileContent = await vscode.workspace.fs.readFile(vscode.Uri.file(filePath));
        let code = Buffer.from(fileContent).toString('utf8');

        // Limit code size to avoid API timeout (max 3000 lines or 100KB)
        const maxLines = 3000;
        const maxChars = 100000;
        const lines = code.split('\n');
        if (lines.length > maxLines) {
          code = lines.slice(0, maxLines).join('\n') + '\n// ... (truncated)';
          this._logger.info(`文件过大，已截断至 ${maxLines} 行`);
        } else if (code.length > maxChars) {
          code = code.substring(0, maxChars) + '\n// ... (truncated)';
          this._logger.info(`文件过大，已截断至 ${maxChars} 字符`);
        }

        const context: CodeContext = {
          projectMetadata: this._state.projectMetadata,
          targetFile: analysis,
          targetCode: code
        };

        const options: ExplainOptions = { level: 3, interactive: true };

        this._logger.ai('正在请求 AI 解释代码...');

        const systemPrompt = buildSystemPrompt();
        const explainPrompt = buildExplainPrompt(context, options);
        const response = await this._claudeClient!.complete(systemPrompt, explainPrompt);

        const explanation = this.parseJsonResponse<GuidedExplanation>(response);
        this._logger.success(`AI 已生成解释（${explanation.steps.length} 个步骤）`);
        this._state.currentExplanation = explanation;
        this._state.currentStepIndex = 0;
      });

      // Execute first step
      await this.executeStep(0);

    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error';
      vscode.window.showErrorMessage(`Failed to explain file: ${msg}`);
      this.postMessage({ type: 'showError', error: msg });
    }
  }

  public async explainSelection(
    filePath: string,
    code: string,
    startLine: number,
    endLine: number
  ): Promise<void> {
    try {
      if (!this._claudeClient) {
        throw new Error('Guide session not initialized. Run Start Guide first.');
      }

      this.postMessage({ type: 'showLoading', message: 'Explaining selection...' });

      await vscode.window.withProgress({
        location: vscode.ProgressLocation.Notification,
        title: 'CodeGuide: Explaining selection...',
        cancellable: false
      }, async () => {
        const context: CodeContext = {
          projectMetadata: this._state.projectMetadata,
          targetCode: code,
          userQuery: `Explain the selected code (lines ${startLine}-${endLine} in ${filePath})`
        };

        const options: ExplainOptions = { level: 3, interactive: true };

        const systemPrompt = buildSystemPrompt();
        const explainPrompt = buildExplainPrompt(context, options);
        const response = await this._claudeClient!.complete(systemPrompt, explainPrompt);

        const explanation = this.parseJsonResponse<GuidedExplanation>(response);
        this._state.currentExplanation = explanation;
        this._state.currentStepIndex = 0;
      });

      await this.executeStep(0);

    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error';
      this._logger.error(`解释失败: ${msg}`);
      vscode.window.showErrorMessage(`Failed to explain selection: ${msg}`);
      this.postMessage({ type: 'showError', error: msg });
    }
  }

  public async executeStep(index: number): Promise<void> {
    try {
      if (!this._state.currentExplanation) {
        throw new Error('No explanation available');
      }

      const steps = this._state.currentExplanation.steps;
      if (index < 0 || index >= steps.length) {
        throw new Error('Invalid step index');
      }

      const step = steps[index];
      this._state.currentStepIndex = index;

      // Resolve file path
      const filePath = this._projectRoot
        ? resolveFilePath(step.file, this._projectRoot)
        : step.file;

      // Log the line numbers for debugging
      console.log(`[CodeGuide] Step ${index + 1}: ${step.title}`);
      console.log(`[CodeGuide] Line numbers: ${step.startLine} - ${step.endLine}`);

      // Validate line numbers
      let validStartLine = step.startLine;
      let validEndLine = step.endLine;

      // Ensure line numbers are positive
      if (validStartLine < 1) {
        console.error(`[CodeGuide] Invalid startLine ${step.startLine}, defaulting to 1`);
        validStartLine = 1;
      }
      if (validEndLine < validStartLine) {
        console.error(`[CodeGuide] Invalid endLine ${step.endLine}, setting to startLine`);
        validEndLine = validStartLine;
      }

      // Navigate to file and line
      await this._codeNavigator.navigateTo(filePath, validStartLine);

      // Highlight code range
      this._codeHighlighter.highlight(filePath, validStartLine, validEndLine);

      // Build progress info
      const currentPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
      const phaseProgress = currentPhase
        ? `Phase ${this._state.currentPhaseIndex + 1}/${this._state.learningPath.phases.length}: ${currentPhase.title}`
        : '';
      const fileProgress = currentPhase
        ? `File ${this._state.currentFileIndex + 1}/${currentPhase.files.length}`
        : '';

      // Notify webview
      this.postMessage({
        type: 'showStep',
        step,
        stepIndex: index,
        totalSteps: steps.length,
        fileProgress,
        phaseProgress
      });

      this.postMessage({
        type: 'updateProgress',
        currentPhase: this._state.currentPhaseIndex + 1,
        totalPhases: this._state.learningPath.phases.length,
        currentFile: this._state.currentFileIndex + 1,
        totalFiles: currentPhase?.files.length || 0
      });

      this._onDidChangeState.fire();

    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error';
      vscode.window.showErrorMessage(`Failed to execute step: ${msg}`);
      this.postMessage({ type: 'showError', error: msg });
    }
  }

  public async nextStep(): Promise<void> {
    if (!this._state.currentExplanation) {
      return;
    }

    const totalSteps = this._state.currentExplanation.steps.length;

    if (this._state.currentStepIndex < totalSteps - 1) {
      await this.executeStep(this._state.currentStepIndex + 1);
    } else {
      await this.nextFile();
    }
  }

  public async previousStep(): Promise<void> {
    if (!this._state.currentExplanation) {
      return;
    }

    if (this._state.currentStepIndex > 0) {
      await this.executeStep(this._state.currentStepIndex - 1);
    } else {
      await this.previousFile();
    }
  }

  public async skipFile(): Promise<void> {
    await this.nextFile();
  }

  private async nextFile(): Promise<void> {
    const currentPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
    if (!currentPhase) { return; }

    // Mark current file as completed
    if (currentPhase.files[this._state.currentFileIndex]) {
      currentPhase.files[this._state.currentFileIndex].completed = true;
    }

    if (this._state.currentFileIndex < currentPhase.files.length - 1) {
      this._state.currentFileIndex++;
      const nextFile = currentPhase.files[this._state.currentFileIndex];
      const fullPath = resolveFilePath(nextFile.path, this._projectRoot!);
      await this.explainFile(fullPath);
    } else {
      await this.nextPhase();
    }
  }

  private async previousFile(): Promise<void> {
    if (this._state.currentFileIndex > 0) {
      this._state.currentFileIndex--;
      const currentPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
      const prevFile = currentPhase.files[this._state.currentFileIndex];
      const fullPath = resolveFilePath(prevFile.path, this._projectRoot!);
      await this.explainFile(fullPath);
    } else {
      await this.previousPhase();
    }
  }

  private async nextPhase(): Promise<void> {
    if (this._state.currentPhaseIndex < this._state.learningPath.phases.length - 1) {
      this._state.currentPhaseIndex++;
      this._state.currentFileIndex = 0;
      this._onDidChangeState.fire();

      const nextPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
      const firstFile = nextPhase.files[0];
      if (firstFile) {
        const fullPath = resolveFilePath(firstFile.path, this._projectRoot!);
        await this.explainFile(fullPath);
      }
    } else {
      // Guide completed
      this.postMessage({ type: 'showOverview', overview: 'Congratulations! You have completed all learning phases.', projectName: this._state.projectMetadata.name });
      vscode.window.showInformationMessage('CodeGuide: You have completed all learning phases!');
    }
  }

  private async previousPhase(): Promise<void> {
    if (this._state.currentPhaseIndex > 0) {
      this._state.currentPhaseIndex--;
      const prevPhase = this._state.learningPath.phases[this._state.currentPhaseIndex];
      this._state.currentFileIndex = prevPhase.files.length - 1;
      this._onDidChangeState.fire();

      const lastFile = prevPhase.files[this._state.currentFileIndex];
      if (lastFile) {
        const fullPath = resolveFilePath(lastFile.path, this._projectRoot!);
        await this.explainFile(fullPath);
      }
    }
  }

  public async askQuestion(question: string): Promise<void> {
    try {
      if (!this._claudeClient) {
        throw new Error('Guide session not initialized');
      }

      this.postMessage({ type: 'showLoading', message: 'Thinking...' });

      // Add user message to history
      const userMessage: ChatMessage = {
        role: 'user',
        content: question,
        timestamp: new Date().toISOString()
      };
      this._state.chatHistory.push(userMessage);

      // Build context from current step
      const currentStep = this._state.currentExplanation?.steps[this._state.currentStepIndex];
      const context: CodeContext = {
        projectMetadata: this._state.projectMetadata,
        targetCode: currentStep?.codeSnippet || '',
        userQuery: question
      };

      const systemPrompt = buildSystemPrompt();
      const chatPrompt = buildChatPrompt(context, this._state.chatHistory);

      const response = await this._claudeClient.complete(systemPrompt, chatPrompt);

      // Add assistant message
      const assistantMessage: ChatMessage = {
        role: 'assistant',
        content: response,
        timestamp: new Date().toISOString()
      };
      this._state.chatHistory.push(assistantMessage);

      // Try to parse JSON response and format it
      const formattedAnswer = this.formatJsonResponse(response);

      // Send response to webview
      this.postMessage({ type: 'showAnswer', answer: formattedAnswer });
      this._onDidChangeState.fire();

    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error';
      vscode.window.showErrorMessage(`Failed to process question: ${msg}`);
      this.postMessage({ type: 'showError', error: msg });
    }
  }

  public stopGuide(): void {
    this._codeHighlighter.clear();

    this._state = {
      projectMetadata: { name: '', type: '', stack: [], entryFiles: [], totalFiles: 0 },
      learningPath: { phases: [], generatedAt: '' },
      currentPhaseIndex: 0,
      currentFileIndex: 0,
      currentStepIndex: 0,
      chatHistory: [],
      isActive: false
    };

    this._onDidChangeState.fire();
    this.postMessage({ type: 'guideStopped' });
  }

  private postMessage(message: ExtensionMessage): void {
    if (this._sidebarView) {
      this._sidebarView.webview.postMessage(message);
    }
  }

  private parseJsonResponse<T>(text: string): T {
    try {
      // Try to extract JSON from markdown code blocks
      const jsonMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[1].trim());
      }

      // Try to parse directly
      return JSON.parse(text.trim());
    } catch (e) {
      // Try to fix incomplete JSON by finding the last complete object
      const trimmed = text.trim();
      console.error('[ClaudeClient] JSON parse error, trying to fix...');

      // Try to find and fix incomplete JSON
      const fixed = this.fixIncompleteJson(trimmed);
      if (fixed) {
        console.error('[ClaudeClient] Successfully fixed JSON');
        return JSON.parse(fixed);
      }

      throw new Error(`Failed to parse JSON response from AI: ${e instanceof Error ? e.message : 'Unknown error'}`);
    }
  }

  /**
   * Try to fix incomplete JSON by finding the last complete object
   */
  private fixIncompleteJson(text: string): string | null {
    // Try to find the closing bracket of the main object
    let depth = 0;
    let lastCompletePos = -1;

    for (let i = 0; i < text.length; i++) {
      if (text[i] === '{') depth++;
      if (text[i] === '}') depth--;

      if (depth === 0 && text[i] === '}') {
        lastCompletePos = i + 1;
      }
    }

    if (lastCompletePos > 0) {
      const result = text.substring(0, lastCompletePos);
      // Verify it's valid JSON
      try {
        JSON.parse(result);
        return result;
      } catch {
        return null;
      }
    }

    return null;
  }

  /**
   * Format JSON response from AI into readable markdown
   */
  private formatJsonResponse(response: string): string {
    const trimmed = response.trim();

    // Try to find JSON in the response (might be wrapped in code blocks)
    let jsonMatch = trimmed.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    let jsonStr = jsonMatch ? jsonMatch[1].trim() : trimmed;

    try {
      const data = JSON.parse(jsonStr);

      // Check if it's a Q&A format with overview, steps, summary
      if (data.overview || data.summary || data.steps) {
        let markdown = '';

        if (data.overview) {
          markdown += `**概述**\n\n${data.overview}\n\n`;
        }

        if (data.steps && Array.isArray(data.steps)) {
          data.steps.forEach((step: any, index: number) => {
            if (step.title) {
              markdown += `### ${index + 1}. ${step.title}\n\n`;
            }
            if (step.content) {
              markdown += `${step.content}\n\n`;
            }
          });
        }

        if (data.summary) {
          markdown += `---\n\n**总结**\n\n${data.summary}`;
        }

        return markdown || response;
      }

      // Check if it's a simple Q&A with answer field
      if (data.answer) {
        return data.answer;
      }

      // Check for other common fields
      if (data.response) {
        return data.response;
      }

      // If JSON but no recognized format, try to stringify nicely
      return JSON.stringify(data, null, 2);

    } catch (e) {
      // Not valid JSON, return original response
      return response;
    }
  }

  public dispose(): void {
    this._codeHighlighter.clear();
    this._onDidChangeState.dispose();
  }
}

