import { useGuideStore } from '../../stores/guideStore';
import { useGuideSession } from '../../hooks/useGuideSession';

export function ProgressBar() {
  const { learningPath, currentPhaseIndex, currentFileIndex, currentStepIndex, currentExplanation, isActive } = useGuideStore();
  const { nextStep, previousStep, skipFile, stopGuide } = useGuideSession();

  if (!isActive || !learningPath) {
    return null;
  }

  const totalPhases = learningPath.phases.length;
  const currentPhase = learningPath.phases[currentPhaseIndex];
  const totalFiles = currentPhase?.files.length || 0;
  const totalSteps = currentExplanation?.steps.length || 0;

  const isFirst = currentStepIndex === 0 && currentFileIndex === 0 && currentPhaseIndex === 0;
  const isLast = currentPhaseIndex === totalPhases - 1 &&
                 currentFileIndex === totalFiles - 1 &&
                 currentStepIndex === totalSteps - 1;

  return (
    <div className="h-10 border-t border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800 flex items-center justify-between px-4">
      <div className="flex items-center gap-4 text-sm">
        <span className="text-gray-600 dark:text-gray-400">
          阶段 {currentPhaseIndex + 1}/{totalPhases}
        </span>
        <span className="text-gray-600 dark:text-gray-400">
          文件 {currentFileIndex + 1}/{totalFiles}
        </span>
        <span className="text-gray-600 dark:text-gray-400">
          步骤 {currentStepIndex + 1}/{totalSteps}
        </span>
      </div>

      <div className="flex items-center gap-2">
        <button
          onClick={previousStep}
          disabled={isFirst}
          className="px-3 py-1 text-sm bg-white dark:bg-slate-700 border border-gray-300 dark:border-slate-600 rounded-md hover:bg-gray-50 dark:hover:bg-slate-600 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          上一步
        </button>
        <button
          onClick={nextStep}
          className="px-3 py-1 text-sm bg-primary-500 text-white rounded-md hover:bg-primary-600"
        >
          {isLast ? '完成' : '下一步'}
        </button>
        <button
          onClick={skipFile}
          className="px-3 py-1 text-sm bg-gray-100 dark:bg-slate-700 rounded-md hover:bg-gray-200 dark:hover:bg-slate-600"
        >
          跳过文件
        </button>
        <button
          onClick={stopGuide}
          className="px-3 py-1 text-sm bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-md hover:bg-red-200 dark:hover:bg-red-900/50"
        >
          停止
        </button>
      </div>
    </div>
  );
}

