  const handleEditorMount = (editor: any, monaco: any) => {
    editorRef.current = editor;
    monacoRef.current = monaco;

    // Define custom theme for highlighting
    monaco.editor.defineTheme('readcode-light', {
      base: 'vs',
      inherit: true,
      rules: [],
      colors: {
        'editor.background': '#ffffff',
      }
    });
    monaco.editor.defineTheme('readcode-dark', {
      base: 'vs-dark',
      inherit: true,
      rules: [],
      colors: {
        'editor.background': '#1e293b',
      }
    });
  };

  // Highlight current step
  useEffect(() => {
    if (!editorRef.current || !monacoRef.current || !currentStep) return;

    const editor = editorRef.current;
    const monaco = monacoRef.current;
    const model = editor.getModel();

    if (!model) return;

    // Clear previous decorations
    decorationsRef.current = editor.deltaDecorations(decorationsRef.current, []);

    // Add new decoration
    const newDecorations = [{
      range: new monaco.Range(
        currentStep.startLine,
        1,
        currentStep.endLine,
        1
      ),
      options: {
        isWholeLine: true,
        className: 'highlighted-line',
        glyphMarginClassName: 'highlighted-glyph',
        overviewRuler: {
          color: '#f59e0b',
          position: 1,
        },
      },
    }];

    decorationsRef.current = editor.deltaDecorations([], newDecorations);

    // Reveal the line
    editor.revealLineInCenter(currentStep.startLine);
  }, [currentStep]);

  if (!projectPath) {
    return (
      <div className="h-full flex items-center justify-center bg-gray-50">
        <p className="text-gray-500">请先打开一个项目</p>
      </div>
    );
  }

  // Show file path
  const fileName = filePath ? filePath.split('/').pop() : '';

  return (
    <div className="h-full w-full flex flex-col">
      {fileName && (
        <div className="px-3 py-1 bg-gray-100 dark:bg-slate-800 text-sm text-gray-600 dark:text-gray-400 border-b border-gray-200 dark:border-slate-700">
          {fileName}
        </div>
      )}
      <div className="flex-1">
        <Editor
          height="100%"
          language={language}
          value={code}
          onMount={handleEditorMount}
          options={{
            readOnly: true,
            minimap: { enabled: true },
            lineNumbers: 'on',
            glyphMargin: true,
            folding: true,
            scrollBeyondLastLine: false,
            fontSize: 14,
            fontFamily: "'SF Mono', Monaco, 'Cascadia Code', monospace",
            automaticLayout: true,
          }}
          theme="readcode-light"
        />
      </div>
    </div>
  );
}

