import Editor from '@monaco-editor/react';
import { useGuideStore } from '../../stores/guideStore';
import { useEffect, useRef, useState } from 'react';

export function CodeEditor() {
  const { projectPath, currentStep, learningPath, currentPhaseIndex, currentFileIndex } = useGuideStore();
  const editorRef = useRef<any>(null);
  const [code, setCode] = useState<string>('');
  const [filePath, setFilePath] = useState<string>('');
  const decorationsRef = useRef<string[]>([]);

  // Load current file content
  useEffect(() => {
    if (!learningPath || !projectPath) return;

    const currentPhase = learningPath.phases[currentPhaseIndex];
    const currentFile = currentPhase?.files[currentFileIndex];

    if (currentFile) {
      const fullPath = `${projectPath}/${currentFile.path}`;
      setFilePath(fullPath);

      if (window.electronAPI) {
        window.electronAPI.project.readFile(fullPath).then((content) => {
          setCode(content);
        });
      }
    }
  }, [projectPath, learningPath, currentPhaseIndex, currentFileIndex]);

  // Handle editor mount
  const handleEditorMount = (editor: any) => {
    editorRef.current = editor;
  };

  // Highlight current step
  useEffect(() => {
    if (!editorRef.current || !currentStep) return;

    const editor = editorRef.current;
    const model = editor.getModel();

    if (!model) return;

    // Clear previous decorations
    decorationsRef.current = editor.deltaDecorations(decorationsRef.current, []);

    // Add new decoration
    const newDecorations = [{
      range: {
        startLineNumber: currentStep.startLine,
        startColumn: 1,
        endLineNumber: currentStep.endLine,
        endColumn: 1,
      },
      options: {
        isWholeLine: true,
        className: 'highlighted-line',
        glyphMarginClassName: 'highlighted-glyph',
        overviewRuler: {
          color: '#f59e0b',
          position: 1,
        },
      },
    }];

    decorationsRef.current = editor.deltaDecorations([], newDecorations);

    // Reveal the line
    editor.revealLineInCenter(currentStep.startLine);
  }, [currentStep]);

  if (!projectPath) {
    return (
      <div className="h-full flex items-center justify-center bg-gray-50">
        <p className="text-gray-500">请先打开一个项目</p>
      </div>
    );
  }

  return (
    <div className="h-full w-full">
      {filePath && (
        <Editor
          height="100%"
          path={filePath}
          defaultLanguage="typescript"
          value={code}
          onMount={handleEditorMount}
          options={{
            readOnly: true,
            minimap: { enabled: true },
            lineNumbers: 'on',
            glyphMargin: true,
            folding: true,
            scrollBeyondLastLine: false,
            fontSize: 14,
            fontFamily: "'SF Mono', Monaco, 'Cascadia Code', monospace",
          }}
          theme="vs-light"
        />
      )}
    </div>
  );
}

