@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f8fafc;
  --color-border: #e2e8f0;
  --color-text: #1e293b;
  --color-text-secondary: #64748b;
  --color-primary: #0ea5e9;
  --color-highlight: rgba(255, 213, 79, 0.15);
}

.dark {
  --color-bg: #1e293b;
  --color-bg-secondary: #0f172a;
  --color-border: #334155;
  --color-text: #f1f5f9;
  --color-text-secondary: #94a3b8;
  --color-primary: #38bdf8;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body, #root {
  height: 100%;
  width: 100%;
  overflow: hidden;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--color-bg-secondary);
}

::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--color-text-secondary);
}

/* Code block styling */
pre {
  background: var(--color-bg-secondary);
  padding: 1rem;
  border-radius: 0.5rem;
  overflow-x: auto;
  font-family: 'SF Mono', Monaco, 'Cascadia Code', monospace;
  font-size: 0.875rem;
}

code {
  font-family: 'SF Mono', Monaco, 'Cascadia Code', monospace;
  font-size: 0.875rem;
}

/* Button base */
.btn {
  @apply px-4 py-2 rounded-md font-medium transition-colors;
}

.btn-primary {
  @apply bg-primary-500 text-white hover:bg-primary-600;
}

.btn-secondary {
  @apply bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300;
}

input.old_string:
.btn-secondary {
  @apply bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300;
}

input.new_string:
.btn-secondary {
  @apply bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300;
}

/* Code highlighting for Monaco Editor */
.highlighted-line {
  background-color: rgba(255, 213, 79, 0.15) !important;
}

.highlighted-glyph {
  background-color: #f59e0b;
  margin-left: 3px;
  width: 3px !important;
}

/* Markdown content styling */
.prose h1 { @apply text-2xl font-bold mt-4 mb-2; }
.prose h2 { @apply text-xl font-bold mt-3 mb-2; }
.prose h3 { @apply text-lg font-semibold mt-2 mb-1; }
.prose p { @apply mb-2; }
.prose ul { @apply list-disc pl-5 mb-2; }
.prose ol { @apply list-decimal pl-5 mb-2; }
.prose li { @apply mb-1; }
.prose code { @apply bg-gray-100 dark:bg-slate-700 px-1 py-0.5 rounded text-sm; }
.prose pre { @apply bg-gray-100 dark:bg-slate-800 p-3 rounded-lg overflow-x-auto; }
.prose pre code { @apply bg-transparent p-0; }
.prose blockquote { @apply border-l-4 border-primary-500 pl-4 italic text-gray-600 dark:text-gray-400; }
.prose a { @apply text-primary-500 hover:underline; }
.prose strong { @apply font-semibold; }
.prose em { @apply italic; }

