import { create } from 'zustand';
import type { ProjectMetadata, LearningPath, GuidedExplanation, ExplainStep, ChatMessage } from '@core/types/index';

interface GuideState {
  // Project state
  projectPath: string | null;
  projectMetadata: ProjectMetadata | null;
  learningPath: LearningPath | null;

  // Learning state
  isActive: boolean;
  isLoading: boolean;
  loadingMessage: string;
  currentPhaseIndex: number;
  currentFileIndex: number;
  currentStepIndex: number;
  currentExplanation: GuidedExplanation | null;
  currentStep: ExplainStep | null;

  // Chat
  chatHistory: ChatMessage[];
  chatInput: string;
  isChatLoading: boolean;

  // UI state
  activeTab: 'content' | 'chat' | 'log';
  showSettings: boolean;

  // Actions
  setProject: (path: string, metadata: ProjectMetadata) => void;
  setLearningPath: (path: LearningPath) => void;
  setLoading: (loading: boolean, message?: string) => void;
  setCurrentStep: (step: ExplainStep | null, stepIndex?: number) => void;
  nextStep: () => void;
  previousStep: () => void;
  nextFile: () => void;
  previousFile: () => void;
  nextPhase: () => void;
  previousPhase: () => void;
  goToStep: (phaseIndex: number, fileIndex: number, stepIndex: number) => void;
  skipFile: () => void;
  stopGuide: () => void;

  // Chat actions
  addChatMessage: (message: ChatMessage) => void;
  setChatInput: (input: string) => void;
  setChatLoading: (loading: boolean) => void;
  clearChat: () => void;

  // UI actions
  setActiveTab: (tab: 'content' | 'chat' | 'log') => void;
  setShowSettings: (show: boolean) => void;
}

export const useGuideStore = create<GuideState>((set, get) => ({
  // Initial state
  projectPath: null,
  projectMetadata: null,
  learningPath: null,
  isActive: false,
  isLoading: false,
  loadingMessage: '',
  currentPhaseIndex: 0,
  currentFileIndex: 0,
  currentStepIndex: 0,
  currentExplanation: null,
  currentStep: null,
  chatHistory: [],
  chatInput: '',
  isChatLoading: false,
  activeTab: 'content',
  showSettings: false,

  // Actions
  setProject: (path, metadata) => set({ projectPath: path, projectMetadata: metadata }),

  setLearningPath: (path) => set({
    learningPath: path,
    isActive: true,
    currentPhaseIndex: 0,
    currentFileIndex: 0,
    currentStepIndex: 0,
  }),

  setLoading: (loading, message = '') => set({ isLoading: loading, loadingMessage: message }),

  setCurrentStep: (step, stepIndex) => set({
    currentStep: step,
    currentStepIndex: stepIndex ?? get().currentStepIndex,
  }),

  nextStep: () => {
    const state = get();
    const { currentExplanation, currentPhaseIndex, currentFileIndex, currentStepIndex, learningPath } = state;

    if (!learningPath) return;

    if (currentExplanation && currentStepIndex < currentExplanation.steps.length - 1) {
      const nextIndex = currentStepIndex + 1;
      set({
        currentStepIndex: nextIndex,
        currentStep: currentExplanation.steps[nextIndex],
      });
    } else {
      // Move to next file
      get().nextFile();
    }
  },

  previousStep: () => {
    const state = get();
    const { currentStepIndex } = state;

    if (currentStepIndex > 0) {
      const prevIndex = currentStepIndex - 1;
      set({
        currentStepIndex: prevIndex,
        currentStep: state.currentExplanation?.steps[prevIndex] || null,
      });
    }
  },

  nextFile: () => {
    const state = get();
    const { currentPhaseIndex, currentFileIndex, learningPath } = state;

    if (!learningPath) return;

    const currentPhase = learningPath.phases[currentPhaseIndex];
    if (currentFileIndex < currentPhase.files.length - 1) {
      set({ currentFileIndex: currentFileIndex + 1 });
    } else if (currentPhaseIndex < learningPath.phases.length - 1) {
      set({ currentPhaseIndex: currentPhaseIndex + 1, currentFileIndex: 0 });
    }
  },

  previousFile: () => {
    const state = get();
    const { currentPhaseIndex, currentFileIndex } = state;

    if (currentFileIndex > 0) {
      set({ currentFileIndex: currentFileIndex - 1 });
    } else if (currentPhaseIndex > 0) {
      const prevPhase = state.learningPath?.phases[currentPhaseIndex - 1];
      set({
        currentPhaseIndex: currentPhaseIndex - 1,
        currentFileIndex: prevPhase ? prevPhase.files.length - 1 : 0,
      });
    }
  },

  nextPhase: () => {
    const state = get();
    const { currentPhaseIndex, learningPath } = state;

    if (learningPath && currentPhaseIndex < learningPath.phases.length - 1) {
      set({ currentPhaseIndex: currentPhaseIndex + 1, currentFileIndex: 0 });
    }
  },

  previousPhase: () => {
    const state = get();
    const { currentPhaseIndex } = state;

    if (currentPhaseIndex > 0) {
      set({ currentPhaseIndex: currentPhaseIndex - 1, currentFileIndex: 0 });
    }
  },

  goToStep: (phaseIndex, fileIndex, stepIndex) => {
    set({
      currentPhaseIndex: phaseIndex,
      currentFileIndex: fileIndex,
      currentStepIndex: stepIndex,
    });
  },

