import { useCallback, useRef } from 'react';
import { useGuideStore } from '../stores/guideStore';
import { GuideSessionCore } from '@core/session/GuideSessionCore';

export function useGuideSession() {
  const coreRef = useRef<GuideSessionCore | null>(null);
  const store = useGuideStore();

  const initCore = useCallback(() => {
    if (!coreRef.current) {
      coreRef.current = new GuideSessionCore();
      coreRef.current.setCallbacks({
        onLoading: (message) => {
          store.setLoading(true, message);
        },
        onLog: (level, message) => {
          console.log(`[${level.toUpperCase()}]`, message);
        },
        onGuideStarted: (learningPath) => {
          store.setLearningPath(learningPath);
          store.setLoading(false);
        },
        onStep: (step, stepIndex, totalSteps) => {
          store.setCurrentStep(step, stepIndex);
        },
        onOverview: (overview, projectName) => {
          store.setLoading(false);
        },
        onError: (error) => {
          store.setLoading(false);
          console.error('Guide error:', error);
        },
        onComplete: () => {
          store.setLoading(false);
        }
      });
    }
    return coreRef.current;
  }, [store]);

  const startGuide = useCallback(async (projectPath: string) => {
    const core = initCore();

    // Get AI config
    let config = { apiKey: '', baseUrl: '', model: '', maxTokens: 4096 };
    if (window.electronAPI) {
      config = await window.electronAPI.ai.getConfig();
    }

    if (!config.apiKey) {
      throw new Error('请先配置 API Key');
    }

    await core.startGuide(projectPath, config);
  }, [initCore]);

  const nextStep = useCallback(async () => {
    if (coreRef.current) {
      await coreRef.current.nextStep();
    }
  }, []);

  const previousStep = useCallback(async () => {
    if (coreRef.current) {
      await coreRef.current.previousStep();
    }
  }, []);

  const skipFile = useCallback(async () => {
    if (coreRef.current) {
      await coreRef.current.skipFile();
    }
  }, []);

  const stopGuide = useCallback(() => {
    if (coreRef.current) {
      coreRef.current.stopGuide();
      store.stopGuide();
    }
  }, [store]);

  const askQuestion = useCallback(async (question: string) => {
    if (!coreRef.current) {
      throw new Error('Guide not started');
    }

    store.setChatLoading(true);
    try {
      const answer = await coreRef.current.askQuestion(question);
      store.addChatMessage({
        role: 'assistant',
        content: answer,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Ask question error:', error);
      throw error;
    } finally {
      store.setChatLoading(false);
    }
  }, [store]);

  return {
    startGuide,
    nextStep,
    previousStep,
    skipFile,
    stopGuide,
    askQuestion
  };
}

