export function useGuideSession() {
  const store = useGuideStore();

  const startGuide = useCallback(async (projectPath: string) => {
    if (!window.electronAPI) {
      throw new Error('请在 Electron 环境中运行');
    }

    store.setLoading(true, '正在启动...');

    // The main process will send events back:
    // - guide:loading
    // - guide:projectMetadata
    // - guide:learningPath
    // - guide:explanation
    // - guide:error

    try {
      const result = await window.electronAPI.guide.startGuide(projectPath);
      return result;
    } catch (error) {
      store.setLoading(false);
      throw error;
    }
  }, [store]);

  const explainFile = useCallback(async (filePath: string) => {
    if (!window.electronAPI) {
      throw new Error('请在 Electron 环境中运行');
    }

    try {
      const result = await window.electronAPI.guide.explainFile(filePath);
      return result;
    } catch (error) {
      throw error;
    }
  }, [store]);

  const nextStep = useCallback(async () => {
    store.nextStep();
  }, [store]);

  const previousStep = useCallback(async () => {
    store.previousStep();
  }, [store]);

  const skipFile = useCallback(async () => {
    store.skipFile();
  }, [store]);

  const stopGuide = useCallback(() => {
    store.stopGuide();
  }, [store]);

  const askQuestion = useCallback(async (question: string) => {
    if (!window.electronAPI) {
      throw new Error('请在 Electron 环境中运行');
    }

    store.setChatLoading(true);
    try {
      // Build context from current state
      const context = {
        projectPath: store.projectPath,
        projectMetadata: store.projectMetadata,
        learningPath: store.learningPath,
        currentPhaseIndex: store.currentPhaseIndex,
        currentFileIndex: store.currentFileIndex,
        currentExplanation: store.currentExplanation,
      };

      const answer = await window.electronAPI.guide.askQuestion(question, context);
      store.addChatMessage({
        role: 'assistant',
        content: answer,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Ask question error:', error);
      throw error;
    } finally {
      store.setChatLoading(false);
    }
  }, [store]);

  return {
    startGuide,
    explainFile,
    nextStep,
    previousStep,
    skipFile,
    stopGuide,
    askQuestion
  };
}

