import { useGuideStore } from '../../stores/guideStore';
import { Toolbar } from './Toolbar';
import { LearningPathTree } from '../learning/LearningPathTree';
import { CodeEditor } from '../editor/CodeEditor';
import { ExplanationPanel } from '../explanation/ExplanationPanel';
import { ChatPanel } from '../chat/ChatPanel';
import { ProgressBar } from '../learning/ProgressBar';

export function AppLayout() {
  const { activeTab } = useGuideStore();

  return (
    <div className="h-full flex flex-col bg-white dark:bg-slate-900">
      <Toolbar />

      <div className="flex-1 flex overflow-hidden">
        {/* Left sidebar - Learning path */}
        <div className="w-64 border-r border-gray-200 dark:border-slate-700 overflow-y-auto">
          <LearningPathTree />
        </div>

        {/* Main content area */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Code editor */}
          <div className="flex-1 overflow-hidden">
            <CodeEditor />
          </div>

          {/* Bottom panel - Explanation or Chat */}
          <div className="h-80 border-t border-gray-200 dark:border-slate-700">
            <div className="h-full flex">
              {/* Tab buttons */}
              <div className="w-32 border-r border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800">
                <button
                  className={`w-full px-3 py-2 text-sm font-medium ${activeTab === 'content' ? 'bg-white dark:bg-slate-700 border-b-2 border-primary-500' : ''}`}
                  onClick={() => useGuideStore.getState().setActiveTab('content')}
                >
                  内容
                </button>
                <button
                  className={`w-full px-3 py-2 text-sm font-medium ${activeTab === 'chat' ? 'bg-white dark:bg-slate-700 border-b-2 border-primary-500' : ''}`}
                  onClick={() => useGuideStore.getState().setActiveTab('chat')}
                >
                  问答
                </button>
              </div>

              {/* Panel content */}
              <div className="flex-1 overflow-hidden">
                {activeTab === 'content' ? <ExplanationPanel /> : <ChatPanel />}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Progress bar */}
      <ProgressBar />
    </div>
  );
}

