     9→  const [filePath, setFilePath] = useState<string>('');
    10→  const [language, setLanguage] = useState<string>('typescript');
    11→  const decorationsRef = useRef<string[]>([]);
    12→  const monacoRef = useRef<any>(null);
    13→
    14→  // Load current file content
    15→  useEffect(() => {
    16→    if (!learningPath || !projectPath) return;
    17→
    18→    const currentPhase = learningPath.phases[currentPhaseIndex];
    19→    const currentFile = currentPhase?.files[currentFileIndex];
    20→
    21→    if (currentFile) {
    22→      const fullPath = `${projectPath}/${currentFile.path}`;
    23→      setFilePath(fullPath);
    24→
    25→      // Determine language from file extension
    26→      const ext = currentFile.path.split('.').pop() || '';
    27→      const langMap: Record<string, string> = {
    28→        'ts': 'typescript',
    29→        'tsx': 'typescript',
    30→        'js': 'javascript',
    31→        'jsx': 'javascript',
    32→        'py': 'python',
    33→        'go': 'go',
    34→        'rs': 'rust',
    35→        'java': 'java',
    36→        'rb': 'ruby',
    37→        'php': 'php',
    38→        'css': 'css',
    39→        'scss': 'scss',
    40→        'html': 'html',
    41→        'json': 'json',
    42→        'md': 'markdown',
    43→      };
    44→      setLanguage(langMap[ext] || 'typescript');
    45→
    46→      if (window.electronAPI) {
    47→        window.electronAPI.project.readFile(fullPath).then((content) => {
    48→          setCode(content);
    49→        }).catch((err) => {
    50→          console.error('Error reading file:', err);
    51→          setCode('// 无法加载文件: ' + err.message);
    52→        });
    53→      }
    54→    }
    55→  }, [projectPath, learningPath, currentPhaseIndex, currentFileIndex]);
    56→
    57→  // Handle editor mount
    58→  const handleEditorMount = (editor: any, monaco: any) => {
    59→    editorRef.current = editor;
    60→    monacoRef.current = monaco;
    61→
    62→    // Define custom theme for highlighting
    63→    monaco.editor.defineTheme('readcode-light', {
    64→      base: 'vs',
    65→      inherit: true,
    66→      rules: [],
    67→      colors: {
    68→        'editor.background': '#ffffff',
    69→      }
    70→    });
    71→    monaco.editor.defineTheme('readcode-dark', {
    72→      base: 'vs-dark',
    73→      inherit: true,
    74→      rules: [],
    75→      colors: {
    76→        'editor.background': '#1e293b',
    77→      }
    78→    });
    79→  };
    80→
    81→  // Highlight current step
    82→  useEffect(() => {
    83→    if (!editorRef.current || !monacoRef.current || !currentStep) return;
    84→
    85→    const editor = editorRef.current;
    86→    const monaco = monacoRef.current;
    87→    const model = editor.getModel();
    88→
    89→    if (!model) return;
    90→
    91→    // Clear previous decorations
    92→    decorationsRef.current = editor.deltaDecorations(decorationsRef.current, []);
    93→
    94→    // Add new decoration
    95→    const newDecorations = [{
    96→      range: new monaco.Range(
