import Editor from '@monaco-editor/react';
import { useGuideStore } from '../../stores/guideStore';
import { useEffect, useRef, useState, useCallback } from 'react';

export function CodeEditor() {
  const { projectPath, currentStep, learningPath, currentPhaseIndex, currentFileIndex } = useGuideStore();
  const editorRef = useRef<any>(null);
  const [code, setCode] = useState<string>('');
  const [filePath, setFilePath] = useState<string>('');
  const [language, setLanguage] = useState<string>('typescript');
  const decorationsRef = useRef<string[]>([]);
  const monacoRef = useRef<any>(null);

  // Load current file content
  useEffect(() => {
    if (!learningPath || !projectPath) return;

    const currentPhase = learningPath.phases[currentPhaseIndex];
    const currentFile = currentPhase?.files[currentFileIndex];

    if (currentFile) {
      const fullPath = `${projectPath}/${currentFile.path}`;
      setFilePath(fullPath);

      // Determine language from file extension
      const ext = currentFile.path.split('.').pop() || '';
      const langMap: Record<string, string> = {
        'ts': 'typescript',
        'tsx': 'typescript',
        'js': 'javascript',
        'jsx': 'javascript',
        'py': 'python',
        'go': 'go',
        'rs': 'rust',
        'java': 'java',
        'rb': 'ruby',
        'php': 'php',
        'css': 'css',
        'scss': 'scss',
        'html': 'html',
        'json': 'json',
        'md': 'markdown',
      };
      setLanguage(langMap[ext] || 'typescript');

      if (window.electronAPI) {
        window.electronAPI.project.readFile(fullPath).then((content) => {
          setCode(content);
        }).catch((err) => {
          console.error('Error reading file:', err);
          setCode('// 无法加载文件: ' + err.message);
        });
      }
    }
  }, [projectPath, learningPath, currentPhaseIndex, currentFileIndex]);

  // Handle editor mount
  const handleEditorMount = (editor: any, monaco: any) => {
    editorRef.current = editor;
    monacoRef.current = monaco;

    // Define custom theme for highlighting
    monaco.editor.defineTheme('readcode-light', {
      base: 'vs',
      inherit: true,
      rules: [],
      colors: {
        'editor.background': '#ffffff',
      }
    });
    monaco.editor.defineTheme('readcode-dark', {
      base: 'vs-dark',
      inherit: true,
      rules: [],
      colors: {
        'editor.background': '#1e293b',
      }
    });
  };

  // Highlight current step
  useEffect(() => {
    if (!editorRef.current || !monacoRef.current || !currentStep) return;

    const editor = editorRef.current;
    const monaco = monacoRef.current;
    const model = editor.getModel();

    if (!model) return;

    // Clear previous decorations
    decorationsRef.current = editor.deltaDecorations(decorationsRef.current, []);

    // Add new decoration
    const newDecorations = [{
      range: new monaco.Range(
        currentStep.startLine,
        1,
        currentStep.endLine,
        1
      ),
      options: {
        isWholeLine: true,
        className: 'highlighted-line',
        glyphMarginClassName: 'highlighted-glyph',
        overviewRuler: {
          color: '#f59e0b',
          position: 1,
        },
      },
    }];

    decorationsRef.current = editor.deltaDecorations([], newDecorations);

    // Reveal the line
    editor.revealLineInCenter(currentStep.startLine);
  }, [currentStep]);

  if (!projectPath) {
    return (
      <div className="h-full flex items-center justify-center bg-gray-50">
        <p className="text-gray-500">请先打开一个项目</p>
      </div>
    );
  }

  // Show file path
  const fileName = filePath ? filePath.split('/').pop() : '';

  return (
    <div className="h-full w-full flex flex-col">
      {fileName && (
        <div className="px-3 py-1 bg-gray-100 dark:bg-slate-800 text-sm text-gray-600 dark:text-gray-400 border-b border-gray-200 dark:border-slate-700">
          {fileName}
        </div>
      )}
      <div className="flex-1">
        <Editor
          height="100%"
          language={language}
          value={code}
          onMount={handleEditorMount}
          options={{
            readOnly: true,
            minimap: { enabled: true },
            lineNumbers: 'on',
            glyphMargin: true,
            folding: true,
            scrollBeyondLastLine: false,
            fontSize: 14,
            fontFamily: "'SF Mono', Monaco, 'Cascadia Code', monospace",
            automaticLayout: true,
          }}
          theme="readcode-light"
        />
      </div>
    </div>
  );
}

