import { useEffect, useRef } from 'react';
import { useGuideStore } from '../stores/guideStore';

export function useIPCEvents() {
  const isFirstRender = useRef(true);

  useEffect(() => {
    if (!window.electronAPI) return;

    const store = useGuideStore.getState();

    // Listen for loading events
    const unsubLoading = window.electronAPI.on('guide:loading', (message: string) => {
      // If message is empty string, set loading to false
      const isLoading = message !== '' && message !== null && message !== undefined;
      useGuideStore.setState({ isLoading, loadingMessage: message || '' });
    });

    // Listen for project metadata
    const unsubMetadata = window.electronAPI.on('guide:projectMetadata', (metadata: any) => {
      const projectPath = useGuideStore.getState().projectPath;
      if (projectPath && metadata) {
        useGuideStore.getState().setProject(projectPath, metadata);
      }
    });

    // Listen for learning path
    const unsubLearningPath = window.electronAPI.on('guide:learningPath', (learningPath: any) => {
      if (learningPath) {
        useGuideStore.getState().setLearningPath(learningPath);
      }
    });

    // Listen for explanation
    const unsubExplanation = window.electronAPI.on('guide:explanation', ({ explanation, filePath }: { explanation: any; filePath: string }) => {
      if (explanation && explanation.steps && explanation.steps.length > 0) {
        useGuideStore.setState({
          currentExplanation: explanation,
          currentStep: explanation.steps[0],
          currentStepIndex: 0,
          isLoading: false,
          loadingMessage: ''
        });
      } else {
        useGuideStore.setState({ isLoading: false, loadingMessage: '' });
      }
    });

    // Listen for errors
    const unsubError = window.electronAPI.on('guide:error', (error: string) => {
      console.error('Guide error:', error);
      useGuideStore.setState({ isLoading: false, loadingMessage: '' });
    });

    // Listen for agent logs
    const unsubLog = window.electronAPI.on('guide:log', (log: { level: string; message: string; timestamp: string }) => {
      console.log(`[AGENT ${log.level.toUpperCase()}]`, log.message);
    });

    return () => {
      unsubLoading();
      unsubMetadata();
      unsubLearningPath();
      unsubExplanation();
      unsubError();
      unsubLog();
    };
  }, [isFirstRender.current]); // Run once on mount
}

