import { useEffect, useRef } from 'react';
import { useGuideStore } from '../stores/guideStore';

export function useFileChangeHandler() {
  const prevIndicesRef = useRef<{ phase: number; file: number } | null>(null);

  useEffect(() => {
    if (!window.electronAPI) return;

    const checkForFileChange = () => {
      const state = useGuideStore.getState();
      const { learningPath, currentPhaseIndex, currentFileIndex, projectPath, isLoading } = state;

      // Skip if still loading or no learning path
      if (isLoading || !learningPath || !projectPath) return;

      const currentPhase = learningPath.phases[currentPhaseIndex];
      const currentFile = currentPhase?.files[currentFileIndex];

      if (!currentFile) return;

      // Check if file changed
      const prev = prevIndicesRef.current;
      if (prev && prev.phase === currentPhaseIndex && prev.file === currentFileIndex) {
        return; // No change
      }

      // Update previous indices
      prevIndicesRef.current = { phase: currentPhaseIndex, file: currentFileIndex };

      // Skip if this is the initial load (first file from guide:startGuide)
      if (!prev) return;

      // File changed - fetch new explanation
      const fullPath = `${projectPath}/${currentFile.path}`;
      console.log('File changed, fetching explanation:', fullPath);

      window.electronAPI.guide.explainFile(fullPath).catch((err) => {
        console.error('Error fetching explanation:', err);
      });
    };

    // Check on state changes
    const unsubscribe = useGuideStore.subscribe((state) => {
      checkForFileChange();
    });

    // Initial check
    checkForFileChange();

    return () => {
      unsubscribe();
    };
  }, []);
}

