import { ipcMain, BrowserWindow } from 'electron'
import { scanProject } from '../../../core/scanner/ProjectScanner'
import { analyzeFile } from '../../../core/scanner/FileAnalyzer'
import * as fs from 'fs/promises'
import * as path from 'path'
import log from 'electron-log'
import { ClaudeClient } from '../../../core/ai/ClaudeClient'
import { buildSystemPrompt } from '../../../core/ai/prompts/system'
import { buildExplainPrompt } from '../../../core/ai/prompts/explain'
import { buildLearnPrompt } from '../../../core/ai/prompts/learn'
import { buildChatPrompt } from '../../../core/ai/prompts/chat'
import * as os from 'os'

let claudeClient: ClaudeClient | null = null
let currentProjectPath: string | null = null

function getClient(): ClaudeClient {
  return claudeClient!
}

const CONFIG_PATH = path.join(os.homedir(), '.readcode', 'config.json')

async function ensureConfigDir(): Promise<void> {
  const dir = path.dirname(CONFIG_PATH)
  await fs.mkdir(dir, { recursive: true })
}

function resolveFilePath(filePath: string): string {
  if (!currentProjectPath) return filePath
  if (path.isAbsolute(filePath)) return filePath
  return path.join(currentProjectPath, filePath)
}

function parseJsonResponse<T>(text: string): T {
  try {
    const jsonMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1].trim());
    }
    return JSON.parse(text.trim());
  } catch (e) {
    const trimmed = text.trim();
    let depth = 0;
    let lastCompletePos = -1;
    for (let i = 0; i < trimmed.length; i++) {
      if (trimmed[i] === '{') depth++;
      if (trimmed[i] === '}') depth--;
      if (depth === 0 && trimmed[i] === '}') lastCompletePos = i + 1;
    }
    if (lastCompletePos > 0) {
      const result = trimmed.substring(0, lastCompletePos);
      try {
        return JSON.parse(result);
      } catch {}
    }
    throw new Error(`Failed to parse JSON: ${e}`);
  }
}

export function registerProjectHandlers(): void {
  // Open folder dialog
  ipcMain.handle('project:openFolder', async () => {
    const { dialog } = await import('electron')
    const result = await dialog.showOpenDialog({
      properties: ['openDirectory'],
      title: 'Select Project Folder'
    })
    if (result.canceled || result.filePaths.length === 0) {
      return null
    }
    currentProjectPath = result.filePaths[0]
    return result.filePaths[0]
  })

  // Scan project
  ipcMain.handle('project:scan', async (_event, projectPath: string) => {
    try {
      log.info('Scanning project:', projectPath)
      currentProjectPath = projectPath
      const metadata = await scanProject(projectPath)
      return metadata
    } catch (error) {
      log.error('Project scan error:', error)
      throw error
    }
  })

  // Analyze file
  ipcMain.handle('project:analyzeFile', async (_event, filePath: string) => {
    try {
      const analysis = await analyzeFile(filePath)
      return analysis
    } catch (error) {
      log.error('File analyze error:', error)
      throw error
    }
  })

  // Read file content
  ipcMain.handle('project:readFile', async (_event, filePath: string) => {
    try {
      const content = await fs.readFile(filePath, 'utf-8')
      return content
    } catch (error) {
      log.error('File read error:', error)
      throw error
    }
  })

  // Get recent projects
  ipcMain.handle('project:getRecentProjects', async () => {
    return []
  })

  // Start guide - generate learning path
  ipcMain.handle('guide:startGuide', async (event, projectPath: string) => {
    try {
      currentProjectPath = projectPath
      const window = BrowserWindow.fromWebContents(event.sender)

      // Get config
      let config = { apiKey: '', baseUrl: '', model: '', maxTokens: 4096 }
      try {
        await ensureConfigDir()
        const configData = await fs.readFile(CONFIG_PATH, 'utf-8')
        config = { ...config, ...JSON.parse(configData) }
      } catch {}

      if (!config.apiKey) {
        throw new Error('请先配置 API Key')
      }

      claudeClient = new ClaudeClient({
        apiKey: config.apiKey,
        baseUrl: config.baseUrl || 'https://api.anthropic.com',
        model: config.model || 'claude-sonnet-4-20250514',
        maxTokens: config.maxTokens || 4096
      })

      // Notify loading
      window?.webContents.send('guide:loading', '正在扫描项目...')
      log.info('Scanning project:', projectPath)

      // Scan project
      const metadata = await scanProject(projectPath)
      window?.webContents.send('guide:projectMetadata', metadata)

      // Analyze key files
      window?.webContents.send('guide:loading', '正在分析关键文件...')
      const filesToAnalyze = [...metadata.entryFiles].slice(0, 15)
      const fileAnalyses = []

      for (const file of filesToAnalyze) {
        try {
          const fullPath = path.join(projectPath, file)
          const analysis = await analyzeFile(fullPath)
          fileAnalyses.push(analysis)
        } catch {}
      }

      // Generate learning path
      window?.webContents.send('guide:loading', '正在生成学习路径...')
      log.info('Generating learning path...')

      const systemPrompt = buildSystemPrompt()
      const learnPrompt = buildLearnPrompt(metadata, fileAnalyses)
      const response = await claudeClient.complete(systemPrompt, learnPrompt)
      const learningPath = parseJsonResponse(response)
      learningPath.generatedAt = new Date().toISOString()

      log.info('Learning path generated:', learningPath.phases.length, 'phases')
      window?.webContents.send('guide:learningPath', learningPath)

      // Explain first file
      const firstFile = learningPath.phases[0]?.files[0]
      if (firstFile) {
        await new Promise(resolve => setTimeout(resolve, 2000))
        const fullPath = resolveFilePath(firstFile.path)

        window?.webContents.send('guide:loading', '正在分析文件...')
        const analysis = await analyzeFile(fullPath)
        let code = await fs.readFile(fullPath, 'utf-8')

        // Limit code size
        const maxLines = 3000
        const lines = code.split('\n')
        if (lines.length > maxLines) {
          code = lines.slice(0, maxLines).join('\n') + '\n// ... (truncated)'
        }

        window?.webContents.send('guide:loading', '正在解释代码...')

        const explainPrompt = buildExplainPrompt({
          projectMetadata: metadata,
          targetFile: analysis,
          targetCode: code
        }, { level: 3 })

        const explanationResponse = await claudeClient.complete(systemPrompt, explainPrompt)
        const explanation = parseJsonResponse(explanationResponse)

        window?.webContents.send('guide:explanation', {
          explanation,
          filePath: fullPath
        })
      }

      window?.webContents.send('guide:loading', '')

      return { success: true }
    } catch (error: any) {
      log.error('Guide error:', error)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })

  // Explain file
  ipcMain.handle('guide:explainFile', async (event, filePath: string) => {
    try {
      const window = BrowserWindow.fromWebContents(event.sender)

      window?.webContents.send('guide:loading', '正在分析文件...')

      const analysis = await analyzeFile(filePath)
      let code = await fs.readFile(filePath, 'utf-8')

      const maxLines = 3000
      const lines = code.split('\n')
      if (lines.length > maxLines) {
        code = lines.slice(0, maxLines).join('\n') + '\n// ... (truncated)'
      }

      window?.webContents.send('guide:loading', '正在解释代码...')

      // Get project metadata from previous scan (stored in main process)
      const metadata = (await scanProject(currentProjectPath!))

      const systemPrompt = buildSystemPrompt()
      const explainPrompt = buildExplainPrompt({
        projectMetadata: metadata,
        targetFile: analysis,
        targetCode: code
      }, { level: 3 })

      const response = await claudeClient!.complete(systemPrompt, explainPrompt)
      const explanation = parseJsonResponse(response)

      window?.webContents.send('guide:explanation', { explanation, filePath })
      window?.webContents.send('guide:loading', '')

      return { success: true }
    } catch (error: any) {
      log.error('Explain file error:', error)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })

  // Ask question
  ipcMain.handle('guide:askQuestion', async (event, question: string, context: any) => {
    try {
      const window = BrowserWindow.fromWebContents(event.sender)
      window?.webContents.send('guide:loading', '思考中...')

      const systemPrompt = buildSystemPrompt()
      const chatPrompt = buildChatPrompt(context, [])
      const response = await claudeClient!.complete(systemPrompt, chatPrompt)

      window?.webContents.send('guide:loading', '')

      return response
    } catch (error: any) {
      log.error('Ask question error:', error)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })
}

