import { contextBridge, ipcRenderer } from 'electron'

export interface ElectronAPI {
  project: {
    openFolder: () => Promise<string | null>
    scan: (projectPath: string) => Promise<any>
    analyzeFile: (filePath: string) => Promise<any>
    readFile: (filePath: string) => Promise<string>
    getRecentProjects: () => Promise<any[]>
  }
  guide: {
    startGuide: (projectPath: string) => Promise<{ success: boolean }>
    explainFile: (filePath: string) => Promise<{ success: boolean }>
    askQuestion: (question: string, context: any) => Promise<string>
  }
  ai: {
    complete: (systemPrompt: string, userPrompt: string) => Promise<string>
    stream: (systemPrompt: string, userPrompt: string) => Promise<void>
    getConfig: () => Promise<any>
    updateConfig: (config: any) => Promise<void>
  }
  store: {
    saveSession: (projectId: string, state: any) => Promise<void>
    loadSession: (projectId: string) => Promise<any | null>
    saveAnnotations: (projectId: string, annotations: any[]) => Promise<void>
    loadAnnotations: (projectId: string) => Promise<any[]>
  }
  system: {
    getAppVersion: () => string
    openExternal: (url: string) => Promise<void>
  }
  on: (channel: string, callback: (...args: any[]) => void) => () => void
}

const electronAPI: ElectronAPI = {
  project: {
    openFolder: () => ipcRenderer.invoke('project:openFolder'),
    scan: (projectPath) => ipcRenderer.invoke('project:scan', projectPath),
    analyzeFile: (filePath) => ipcRenderer.invoke('project:analyzeFile', filePath),
    readFile: (filePath) => ipcRenderer.invoke('project:readFile', filePath),
    getRecentProjects: () => ipcRenderer.invoke('project:getRecentProjects')
  },
  guide: {
    startGuide: (projectPath) => ipcRenderer.invoke('guide:startGuide', projectPath),
    explainFile: (filePath) => ipcRenderer.invoke('guide:explainFile', filePath),
    askQuestion: (question, context) => ipcRenderer.invoke('guide:askQuestion', question, context)
  },
  ai: {
    complete: (systemPrompt, userPrompt) => ipcRenderer.invoke('ai:complete', systemPrompt, userPrompt),
    stream: (systemPrompt, userPrompt) => ipcRenderer.invoke('ai:stream', systemPrompt, userPrompt),
    getConfig: () => ipcRenderer.invoke('ai:getConfig'),
    updateConfig: (config) => ipcRenderer.invoke('ai:updateConfig', config)
  },
  store: {
    saveSession: (projectId, state) => ipcRenderer.invoke('store:saveSession', projectId, state),
    loadSession: (projectId) => ipcRenderer.invoke('store:loadSession', projectId),
    saveAnnotations: (projectId, annotations) => ipcRenderer.invoke('store:saveAnnotations', projectId, annotations),
    loadAnnotations: (projectId) => ipcRenderer.invoke('store:loadAnnotations', projectId)
  },
  system: {
    getAppVersion: () => ipcRenderer.invoke('system:getAppVersion'),
    openExternal: (url) => ipcRenderer.invoke('system:openExternal', url)
  },
  on: (channel, callback) => {
    const subscription = (_event: any, ...args: any[]) => callback(...args)
    ipcRenderer.on(channel, subscription)
    return () => {
      ipcRenderer.removeListener(channel, subscription)
    }
  }
}

contextBridge.exposeInMainWorld('electronAPI', electronAPI)

