interface LogEntry {
  level: 'info' | 'warn' | 'error' | 'debug';
  message: string;
  timestamp: string;
}

export function AgentLogPanel() {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [isExpanded, setIsExpanded] = useState(false);
  const [cacheInfo, setCacheInfo] = useState({ ttl: 30000, maxSize: 100, currentSize: 0 });
  const [ttlInput, setTtlInput] = useState('30');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!window.electronAPI) return;

    // Fetch initial logs
    window.electronAPI.guide.getLogs().then(setLogs);

    // Fetch cache info
    window.electronAPI.guide.getCacheConfig().then(setCacheInfo);

    // Subscribe to new logs
    const unsubLog = window.electronAPI.on('guide:log', (log: LogEntry) => {
      setLogs(prev => [...prev.slice(-499), log]);
    });

    // Auto scroll to bottom
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }

    return () => {
      unsubLog();
    };
  }, []);

  const handleClearLogs = async () => {
    if (window.electronAPI) {
      await window.electronAPI.guide.clearLogs();
      setLogs([]);
    }
  };

  const handleClearCache = async () => {
    if (window.electronAPI) {
      await window.electronAPI.guide.clearCache();
      const info = await window.electronAPI.guide.getCacheConfig();
      setCacheInfo(info);
    }
  };

  const handleTtlChange = async () => {
    const ttlMinutes = parseInt(ttlInput) || 30;
    const ttlMs = ttlMinutes * 60 * 1000;
    if (window.electronAPI) {
      await window.electronAPI.guide.setCacheTTL(ttlMs);
      const info = await window.electronAPI.guide.getCacheConfig();
      setCacheInfo(info);
    }
  };

  const getLevelColor = (level: string) => {
    switch (level) {
      case 'error': return 'text-red-500';
      case 'warn': return 'text-yellow-500';
      case 'debug': return 'text-gray-500';
      default: return 'text-blue-500';
    }
  };

  return (
    <div className="border-t border-gray-200 dark:border-slate-700">
      {/* Header */}
      <div
        className="flex items-center justify-between px-3 py-2 bg-gray-50 dark:bg-slate-800 cursor-pointer"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-2">
          <svg
            className={`w-4 h-4 transition-transform ${isExpanded ? 'rotate-90' : ''}`}
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
            Agent 工作日志
          </span>
          <span className="text-xs text-gray-500">
            ({logs.length} 条)
          </span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-gray-500">
            缓存: {cacheInfo.currentSize}/{cacheInfo.maxSize}
          </span>
          <button
            onClick={(e) => {
              e.stopPropagation();
              handleClearCache();
            }}
            className="text-xs px-2 py-1 bg-gray-200 dark:bg-slate-700 rounded hover:bg-gray-300 dark:hover:bg-slate-600"
          >
            清除缓存
          </button>
        </div>
      </div>

      {/* Expanded content */}
      {isExpanded && (
        <div className="flex flex-col h-64">
          {/* Cache settings */}
          <div className="px-3 py-2 border-b border-gray-200 dark:border-slate-700 flex items-center gap-4">
            <span className="text-xs text-gray-600 dark:text-gray-400">
              缓存 TTL (分钟):
            </span>
            <input
              type="number"
              value={ttlInput}
              onChange={(e) => setTtlInput(e.target.value)}
              className="w-16 px-2 py-1 text-xs border border-gray-300 dark:border-slate-600 rounded bg-white dark:bg-slate-800"
              min="1"
              max="1440"
            />
            <button
              onClick={handleTtlChange}
              className="text-xs px-2 py-1 bg-primary-500 text-white rounded hover:bg-primary-600"
            >
              设置
            </button>
            <span className="text-xs text-gray-500">
              当前: {Math.round(cacheInfo.ttl / 60000)} 分钟
            </span>
          </div>

          {/* Log content */}
          <div
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-2 font-mono text-xs"
          >
            {logs.length === 0 ? (
              <div className="text-gray-400 text-center py-4">
                暂无日志
              </div>
            ) : (
              logs.map((log, index) => (
                <div key={index} className="mb-1 flex gap-2">
                  <span className="text-gray-400 shrink-0">
                    {new Date(log.timestamp).toLocaleTimeString()}
                  </span>
                  <span className={`shrink-0 uppercase ${getLevelColor(log.level)}`}>
                    [{log.level}]
                  </span>
                  <span className="text-gray-700 dark:text-gray-300">
                    {log.message}
                  </span>
                </div>
              ))
            )}
          </div>

          {/* Footer actions */}
          <div className="px-3 py-2 border-t border-gray-200 dark:border-slate-700 flex justify-end">
            <button
              onClick={handleClearLogs}
              className="text-xs px-3 py-1 bg-gray-200 dark:bg-slate-700 rounded hover:bg-gray-300 dark:hover:bg-slate-600"
            >
              清除日志
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

