import { useGuideStore } from '../../stores/guideStore';

export function Toolbar() {
  const { projectMetadata, isActive, stopGuide, setShowSettings } = useGuideStore();

  const handleNewProject = async () => {
    if (window.electronAPI) {
      const path = await window.electronAPI.project.openFolder();
      if (path) {
        // TODO: Load project
        window.location.reload();
      }
    }
  };

  return (
    <div className="h-12 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between px-4 bg-gray-50 dark:bg-slate-800">
      <div className="flex items-center gap-4">
        <h1 className="text-lg font-semibold text-gray-900 dark:text-white">ReadCode</h1>
        {projectMetadata && (
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {projectMetadata.name}
          </span>
        )}
      </div>

      <div className="flex items-center gap-2">
        <button
          onClick={handleNewProject}
          className="px-3 py-1.5 text-sm bg-white dark:bg-slate-700 border border-gray-300 dark:border-slate-600 rounded-md hover:bg-gray-50 dark:hover:bg-slate-600"
        >
          打开项目
        </button>

        {isActive && (
          <button
            onClick={stopGuide}
            className="px-3 py-1.5 text-sm bg-gray-100 dark:bg-slate-700 rounded-md hover:bg-gray-200 dark:hover:bg-slate-600"
          >
            停止学习
          </button>
        )}

        <button
          onClick={() => setShowSettings(true)}
          className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
        </button>
      </div>
    </div>
  );
}

