import { useState, useEffect } from 'react';
import { useGuideStore } from '../../stores/guideStore';

export function Toolbar() {
  const { projectMetadata, isActive, stopGuide, setShowSettings } = useGuideStore();
  const [isMaximized, setIsMaximized] = useState(false);

  useEffect(() => {
    // Check initial maximized state
    if (window.electronAPI) {
      window.electronAPI.window.isMaximized().then(setIsMaximized);
    }
  }, []);

  const handleMinimize = () => {
    window.electronAPI?.window.minimize();
  };

  const handleMaximize = async () => {
    await window.electronAPI?.window.maximize();
    const maximized = await window.electronAPI?.window.isMaximized();
    setIsMaximized(maximized ?? false);
  };

  const handleClose = () => {
    window.electronAPI?.window.close();
  };

  const handleNewProject = async () => {
    if (window.electronAPI) {
      const path = await window.electronAPI.project.openFolder();
      if (path) {
        window.location.reload();
      }
    }
  };

  return (
    <div className="h-10 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between bg-gray-50 dark:bg-slate-800 select-none"
         style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}>
      {/* Left: App title and project info */}
      <div className="flex items-center gap-4 px-4" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
        <h1 className="text-base font-semibold text-gray-900 dark:text-white">ReadCode</h1>
        {projectMetadata && (
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {projectMetadata.name}
          </span>
        )}
      </div>

      {/* Center: Actions (draggable area) */}
      <div className="flex-1 flex items-center justify-center gap-2" style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}>
        <button
          onClick={handleNewProject}
          style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}
          className="px-3 py-1 text-xs bg-white dark:bg-slate-700 border border-gray-300 dark:border-slate-600 rounded-md hover:bg-gray-50 dark:hover:bg-slate-600"
        >
          打开项目
        </button>

        {isActive && (
          <button
            onClick={stopGuide}
            style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}
            className="px-3 py-1 text-xs bg-gray-100 dark:bg-slate-700 rounded-md hover:bg-gray-200 dark:hover:bg-slate-600"
          >
            停止学习
          </button>
        )}

        <button
          onClick={() => setShowSettings(true)}
          style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}
          className="p-1.5 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
        </button>
      </div>

      {/* Right: Window controls */}
      <div className="flex items-center" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
        {/* Minimize */}
        <button
          onClick={handleMinimize}
          className="w-11 h-10 flex items-center justify-center hover:bg-gray-200 dark:hover:bg-slate-700"
        >
          <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
            <rect y="5" width="12" height="1" fill="currentColor" />
          </svg>
        </button>

        {/* Maximize/Restore */}
        <button
          onClick={handleMaximize}
          className="w-11 h-10 flex items-center justify-center hover:bg-gray-200 dark:hover:bg-slate-700"
        >
          {isMaximized ? (
            <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
              <rect x="2" y="0" width="8" height="8" fill="none" stroke="currentColor" strokeWidth="1" />
              <rect x="0" y="2" width="8" height="8" fill="none" stroke="currentColor" strokeWidth="1" />
              <rect x="0" y="2" width="8" height="8" fill="currentColor" fillOpacity="0.1" />
            </svg>
          ) : (
            <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
              <rect x="0.5" y="0.5" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="1" />
            </svg>
          )}
        </button>

        {/* Close */}
        <button
          onClick={handleClose}
          className="w-11 h-10 flex items-center justify-center hover:bg-red-500 hover:text-white"
        >
          <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
            <path d="M1 1L11 11M1 11L11 1" stroke="currentColor" strokeWidth="1.5" />
          </svg>
        </button>
      </div>
    </div>
  );
}

