import { useState, useEffect } from 'react';
import { useGuideStore } from '../../stores/guideStore';
import { useGuideSession } from '../../hooks/useGuideSession';

export function ProjectSelector() {
  const { setLoading } = useGuideStore();
  const { startGuide } = useGuideSession();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [isMaximized, setIsMaximized] = useState(false);

  useEffect(() => {
    // Check initial maximized state
    if (window.electronAPI) {
      window.electronAPI.window.isMaximized().then(setIsMaximized);
    }
  }, []);

  const handleMinimize = () => {
    window.electronAPI?.window.minimize();
  };

  const handleMaximize = async () => {
    await window.electronAPI?.window.maximize();
    const maximized = await window.electronAPI?.window.isMaximized();
    setIsMaximized(maximized ?? false);
  };

  const handleClose = () => {
    window.electronAPI?.window.close();
  };

  const handleOpenProject = async () => {
    if (!window.electronAPI) {
      alert('请在 Electron 环境中运行');
      return;
    }

    const path = await window.electronAPI.project.openFolder();
    if (!path) return;

    setIsLoading(true);
    setLoading(true, '正在启动...');
    setError('');

    try {
      await startGuide(path);
    } catch (err) {
      console.error('Error opening project:', err);
      setError((err as Error).message || '打开项目失败');
      setLoading(false);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-gray-50 dark:bg-slate-900">
      {/* Custom title bar for drag */}
      <div className="h-10 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between bg-gray-50 dark:bg-slate-800 select-none"
           style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}>

        {/* Left: App title */}
        <div className="flex items-center gap-4 px-4">
          <h1 className="text-base font-semibold text-gray-900 dark:text-white">ReadCode</h1>
        </div>

        {/* Right: Window controls */}
        <div className="flex items-center" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
          {/* Minimize */}
          <button
            onClick={handleMinimize}
            className="w-11 h-10 flex items-center justify-center hover:bg-gray-200 dark:hover:bg-slate-700"
          >
            <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
              <rect y="5" width="12" height="1" fill="currentColor" />
            </svg>
          </button>

          {/* Maximize/Restore */}
          <button
            onClick={handleMaximize}
            className="w-11 h-10 flex items-center justify-center hover:bg-gray-200 dark:hover:bg-slate-700"
          >
            {isMaximized ? (
              <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
                <rect x="2" y="0" width="8" height="8" fill="none" stroke="currentColor" strokeWidth="1" />
                <rect x="0" y="2" width="8" height="8" fill="none" stroke="currentColor" strokeWidth="1" />
                <rect x="0" y="2" width="8" height="8" fill="currentColor" fillOpacity="0.1" />
              </svg>
            ) : (
              <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
                <rect x="0.5" y="0.5" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="1" />
              </svg>
            )}
          </button>

          {/* Close */}
          <button
            onClick={handleClose}
            className="w-11 h-10 flex items-center justify-center hover:bg-red-500 hover:text-white"
          >
            <svg className="w-3 h-3 text-gray-600 dark:text-gray-400" viewBox="0 0 12 12">
              <path d="M1 1L11 11M1 11L11 1" stroke="currentColor" strokeWidth="1.5" />
            </svg>
          </button>
        </div>
      </div>

      {/* Main content */}
      <div className="flex-1 flex flex-col items-center justify-center">
        <div className="text-center max-w-md">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
            ReadCode
          </h1>
          <p className="text-gray-500 dark:text-gray-400 mb-8">
            AI 驱动的交互式代码学习工具
          </p>

          {error && (
            <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-lg text-sm">
              {error}
            </div>
          )}

          <button
            onClick={handleOpenProject}
            disabled={isLoading}
            className="px-6 py-3 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors disabled:opacity-50"
          >
            {isLoading ? '加载中...' : '打开项目文件夹'}
          </button>

          <p className="mt-4 text-sm text-gray-400">
            选择一个项目文件夹，AI 将自动生成学习路径
          </p>
        </div>
      </div>
    </div>
  );
}

