import { useState } from 'react';
import { useGuideStore } from '../../stores/guideStore';
import { useGuideSession } from '../../hooks/useGuideSession';

export function ProjectSelector() {
  const { setLoading } = useGuideStore();
  const { startGuide } = useGuideSession();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleOpenProject = async () => {
    if (!window.electronAPI) {
      alert('请在 Electron 环境中运行');
      return;
    }

    const path = await window.electronAPI.project.openFolder();
    if (!path) return;

    setIsLoading(true);
    setLoading(true, '正在启动...');
    setError('');

    try {
      // The main process will handle:
      // 1. Scanning project
      // 2. Generating learning path
      // 3. Explaining the first file
      // All events will be sent back via IPC
      await startGuide(path);
    } catch (err) {
      console.error('Error opening project:', err);
      setError((err as Error).message || '打开项目失败');
      setLoading(false);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col items-center justify-center bg-gray-50 dark:bg-slate-900">
      <div className="text-center max-w-md">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
          ReadCode
        </h1>
        <p className="text-gray-500 dark:text-gray-400 mb-8">
          AI 驱动的交互式代码学习工具
        </p>

        {error && (
          <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-lg text-sm">
            {error}
          </div>
        )}

        <button
          onClick={handleOpenProject}
          disabled={isLoading}
          className="px-6 py-3 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors disabled:opacity-50"
        >
          {isLoading ? '加载中...' : '打开项目文件夹'}
        </button>

        <p className="mt-4 text-sm text-gray-400">
          选择一个项目文件夹，AI 将自动生成学习路径
        </p>
      </div>
    </div>
  );
}

