import { promises as fs } from 'fs';
import path from 'path';
import { globby } from 'globby';
import type { ProjectMetadata, DirectoryNode } from '../types/index';

const IGNORE_DIRS = ['node_modules', '.git', 'dist', 'build', 'coverage', '.next', '.nuxt', 'out'];
const IGNORE_FILES = ['.DS_Store', 'Thumbs.db'];

export class ProjectScanner {
  private projectRoot: string;

  constructor(projectRoot: string) {
    this.projectRoot = projectRoot;
  }

  async scan(): Promise<ProjectMetadata> {
    const [projectType, directoryTree, entryFiles, dependencies, totalFiles] = await Promise.all([
      this.detectProjectType(),
      this.buildDirectoryTree(),
      this.findEntryFiles(),
      this.readDependencies(),
      this.countFiles(),
    ]);

    const projectName = path.basename(this.projectRoot);
    const stack = this.inferStack(projectType, dependencies);

    return {
      name: projectName,
      type: projectType,
      stack,
      totalFiles,
      entryFiles,
      directoryTree,
    };
  }

  private async detectProjectType(): Promise<string> {
    const packageJsonPath = path.join(this.projectRoot, 'package.json');

    try {
      const packageJson = JSON.parse(await fs.readFile(packageJsonPath, 'utf-8'));
      const deps = { ...packageJson.dependencies, ...packageJson.devDependencies };

      if (deps['react']) return 'react';
      if (deps['vue']) return 'vue';
      if (deps['next']) return 'next';
      if (deps['express'] || deps['koa'] || deps['fastify']) return 'node-server';
      if (packageJson.type === 'module' || deps['typescript']) return 'node';
    } catch {
      // No package.json
    }

    if (await this.fileExists('requirements.txt') || await this.fileExists('setup.py')) {
      return 'python';
    }
    if (await this.fileExists('go.mod')) {
      return 'go';
    }
    if (await this.fileExists('Cargo.toml')) {
      return 'rust';
    }
    if (await this.fileExists('pom.xml') || await this.fileExists('build.gradle')) {
      return 'java';
    }

    return 'unknown';
  }

  private async buildDirectoryTree(dir: string = this.projectRoot, depth: number = 0): Promise<DirectoryNode> {
    const name = path.basename(dir);
    const stats = await fs.stat(dir);

    if (!stats.isDirectory()) {
      return { name, type: 'file', path: dir };
    }

    if (depth > 4 || IGNORE_DIRS.includes(name)) {
      return { name, type: 'directory', path: dir, children: [] };
    }

    const entries = await fs.readdir(dir);
    const children: DirectoryNode[] = [];

    for (const entry of entries) {
      if (IGNORE_FILES.includes(entry)) continue;

      const fullPath = path.join(dir, entry);
      try {
        const child = await this.buildDirectoryTree(fullPath, depth + 1);
        children.push(child);
      } catch {
        // Skip inaccessible files
      }
    }

    return { name, type: 'directory', path: dir, children };
  }

  private async findEntryFiles(): Promise<string[]> {
    const entryPatterns = [
      'index.{js,ts,jsx,tsx}',
      'main.{js,ts,jsx,tsx}',
      'app.{js,ts,jsx,tsx}',
      'src/index.{js,ts,jsx,tsx}',
      'src/main.{js,ts,jsx,tsx}',
      'src/app.{js,ts,jsx,tsx}',
    ];

    const files = await globby(entryPatterns, {
      cwd: this.projectRoot,
      ignore: IGNORE_DIRS,
      absolute: false,
    });

    return files;
  }

  private async readDependencies(): Promise<Record<string, string>> {
    const packageJsonPath = path.join(this.projectRoot, 'package.json');

    try {
      const packageJson = JSON.parse(await fs.readFile(packageJsonPath, 'utf-8'));
      return { ...packageJson.dependencies, ...packageJson.devDependencies };
    } catch {
      return {};
    }
  }

  private async countFiles(): Promise<number> {
    const files = await globby('**/*', {
      cwd: this.projectRoot,
      ignore: IGNORE_DIRS,
      onlyFiles: true,
    });

    return files.length;
  }

  private inferStack(projectType: string, dependencies: Record<string, string>): string[] {
    const stack: string[] = [];

    if (projectType !== 'unknown') {
      stack.push(projectType);
    }

    if (dependencies['typescript']) {
      stack.push('TypeScript');
    }

    if (dependencies['react']) stack.push('React');
    if (dependencies['vue']) stack.push('Vue');
    if (dependencies['next']) stack.push('Next.js');
    if (dependencies['express']) stack.push('Express');
    if (dependencies['tailwindcss']) stack.push('Tailwind CSS');

    return stack;
  }

  private async fileExists(filename: string): Promise<boolean> {
    try {
      await fs.access(path.join(this.projectRoot, filename));
      return true;
    } catch {
      return false;
    }
  }
}

export async function scanProject(projectPath: string): Promise<ProjectMetadata> {
  const scanner = new ProjectScanner(projectPath);
  return scanner.scan();
}

