import { ipcMain, BrowserWindow } from 'electron'
import { scanProject } from '../../../core/scanner/ProjectScanner'
import { analyzeFile } from '../../../core/scanner/FileAnalyzer'
import * as fs from 'fs/promises'
import * as path from 'path'
import log from 'electron-log'
import { ClaudeClient } from '../../../core/ai/ClaudeClient'
import { buildSystemPrompt } from '../../../core/ai/prompts/system'
import { buildExplainPrompt } from '../../../core/ai/prompts/explain'
import { buildLearnPrompt } from '../../../core/ai/prompts/learn'
import { buildChatPrompt } from '../../../core/ai/prompts/chat'
import * as os from 'os'

// Cache configuration
interface CacheConfig {
  ttl: number // Time to live in milliseconds
  maxSize: number // Maximum number of cached items
}

interface CacheEntry<T> {
  data: T
  timestamp: number
}

// Explanation cache
const explanationCache = new Map<string, CacheEntry<any>>()
let cacheConfig: CacheConfig = {
  ttl: 30 * 60 * 1000, // Default 30 minutes
  maxSize: 100
}

// Agent log storage
interface AgentLog {
  level: 'info' | 'warn' | 'error' | 'debug'
  message: string
  timestamp: string
}
const agentLogs: AgentLog[] = []
const MAX_LOGS = 500

let claudeClient: ClaudeClient | null = null
let currentProjectPath: string | null = null

function getClient(): ClaudeClient {
  return claudeClient!
}

const CONFIG_PATH = path.join(os.homedir(), '.readcode', 'config.json')
const CACHE_CONFIG_PATH = path.join(os.homedir(), '.readcode', 'cache-config.json')

async function ensureConfigDir(): Promise<void> {
  const dir = path.dirname(CONFIG_PATH)
  await fs.mkdir(dir, { recursive: true })
}

// Load cache config
async function loadCacheConfig(): Promise<void> {
  try {
    await ensureConfigDir()
    const data = await fs.readFile(CACHE_CONFIG_PATH, 'utf-8')
    cacheConfig = { ...cacheConfig, ...JSON.parse(data) }
  } catch {}
}

// Save cache config
async function saveCacheConfig(): Promise<void> {
  try {
    await ensureConfigDir()
    await fs.writeFile(CACHE_CONFIG_PATH, JSON.stringify(cacheConfig, null, 2))
  } catch {}
}

// Get cache TTL (can be set by user)
function getCacheTTL(): number {
  return cacheConfig.ttl
}

// Set cache TTL
function setCacheTTL(ttl: number): void {
  cacheConfig.ttl = ttl
  saveCacheConfig()
}

// Clear cache
function clearExplanationCache(): void {
  explanationCache.clear()
  log.info('Explanation cache cleared')
}

// Check if file exists
async function fileExists(filePath: string): Promise<boolean> {
  try {
    await fs.access(filePath)
    return true
  } catch {
    return false
  }
}

// Get cached explanation
function getCachedExplanation(filePath: string): any | null {
  const entry = explanationCache.get(filePath)
  if (!entry) return null

  const now = Date.now()
  if (now - entry.timestamp > cacheConfig.ttl) {
    // Cache expired
    explanationCache.delete(filePath)
    return null
  }

  return entry.data
}

// Set cached explanation
function setCachedExplanation(filePath: string, explanation: any): void {
  // Check cache size limit
  if (explanationCache.size >= cacheConfig.maxSize) {
    // Remove oldest entry
    let oldestKey: string | null = null
    let oldestTime = Infinity
    for (const [key, entry] of explanationCache) {
      if (entry.timestamp < oldestTime) {
        oldestTime = entry.timestamp
        oldestKey = key
      }
    }
    if (oldestKey) {
      explanationCache.delete(oldestKey)
    }
  }

  explanationCache.set(filePath, {
    data: explanation,
    timestamp: Date.now()
  })
}

// Send log to renderer
function sendLog(window: BrowserWindow | null, level: AgentLog['level'], message: string): void {
  const logEntry: AgentLog = {
    level,
    message,
    timestamp: new Date().toISOString()
  }

  // Store locally
  agentLogs.push(logEntry)
  if (agentLogs.length > MAX_LOGS) {
    agentLogs.shift()
  }

  // Send to renderer
  window?.webContents.send('guide:log', logEntry)

  // Also log to electron-log
  switch (level) {
    case 'error':
      log.error('[AGENT]', message)
      break
    case 'warn':
      log.warn('[AGENT]', message)
      break
    case 'debug':
      log.debug('[AGENT]', message)
      break
    default:
      log.info('[AGENT]', message)
  }
}

function resolveFilePath(filePath: string): string {
  if (!currentProjectPath) return filePath
  if (path.isAbsolute(filePath)) return filePath
  return path.join(currentProjectPath, filePath)
}

function parseJsonResponse<T>(text: string): T {
  try {
    const jsonMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1].trim());
    }
    return JSON.parse(text.trim());
  } catch (e) {
    const trimmed = text.trim();
    let depth = 0;
    let lastCompletePos = -1;
    for (let i = 0; i < trimmed.length; i++) {
      if (trimmed[i] === '{') depth++;
      if (trimmed[i] === '}') depth--;
      if (depth === 0 && trimmed[i] === '}') lastCompletePos = i + 1;
    }
    if (lastCompletePos > 0) {
      const result = trimmed.substring(0, lastCompletePos);
      try {
        return JSON.parse(result);
      } catch {}
    }
    throw new Error(`Failed to parse JSON: ${e}`);
  }
}

// Initialize on module load
loadCacheConfig()

export function registerProjectHandlers(): void {
  // Open folder dialog
  ipcMain.handle('project:openFolder', async () => {
    const { dialog } = await import('electron')
    const result = await dialog.showOpenDialog({
      properties: ['openDirectory'],
      title: 'Select Project Folder'
    })
    if (result.canceled || result.filePaths.length === 0) {
      return null
    }
    currentProjectPath = result.filePaths[0]
    return result.filePaths[0]
  })

  // Scan project
  ipcMain.handle('project:scan', async (_event, projectPath: string) => {
    try {
      log.info('Scanning project:', projectPath)
      currentProjectPath = projectPath
      const metadata = await scanProject(projectPath)
      return metadata
    } catch (error) {
      log.error('Project scan error:', error)
      throw error
    }
  })

  // Analyze file
  ipcMain.handle('project:analyzeFile', async (_event, filePath: string) => {
    try {
      const analysis = await analyzeFile(filePath)
      return analysis
    } catch (error) {
      log.error('File analyze error:', error)
      throw error
    }
  })

  // Read file content
  ipcMain.handle('project:readFile', async (_event, filePath: string) => {
    try {
      const content = await fs.readFile(filePath, 'utf-8')
      return content
    } catch (error) {
      log.error('File read error:', error)
      throw error
    }
  })

  // Get recent projects
  ipcMain.handle('project:getRecentProjects', async () => {
    return []
  })

  // Get cache config
  ipcMain.handle('guide:getCacheConfig', async () => {
    return {
      ttl: cacheConfig.ttl,
      maxSize: cacheConfig.maxSize,
      currentSize: explanationCache.size
    }
  })

  // Set cache TTL
  ipcMain.handle('guide:setCacheTTL', async (_event, ttl: number) => {
    setCacheTTL(ttl)
    return { success: true }
  })

  // Clear explanation cache
  ipcMain.handle('guide:clearCache', async () => {
    clearExplanationCache()
    return { success: true }
  })

  // Get agent logs
  ipcMain.handle('guide:getLogs', async () => {
    return [...agentLogs]
  })

  // Clear agent logs
  ipcMain.handle('guide:clearLogs', async () => {
    agentLogs.length = 0
    return { success: true }
  })

  // Start guide - generate learning path
  ipcMain.handle('guide:startGuide', async (event, projectPath: string) => {
    const window = BrowserWindow.fromWebContents(event.sender)

    try {
      currentProjectPath = projectPath
      sendLog(window, 'info', `Starting guide for project: ${projectPath}`)

      // Get config
      let config = { apiKey: '', baseUrl: '', model: '', maxTokens: 4096 }
      try {
        await ensureConfigDir()
        const configData = await fs.readFile(CONFIG_PATH, 'utf-8')
        config = { ...config, ...JSON.parse(configData) }
      } catch {}

      if (!config.apiKey) {
        throw new Error('请先配置 API Key')
      }

      claudeClient = new ClaudeClient({
        apiKey: config.apiKey,
        baseUrl: config.baseUrl || 'https://api.anthropic.com',
        model: config.model || 'claude-sonnet-4-20250514',
        maxTokens: config.maxTokens || 4096
      })

      // Notify loading
      window?.webContents.send('guide:loading', '正在扫描项目...')
      sendLog(window, 'info', 'Scanning project...')

      // Scan project
      const metadata = await scanProject(projectPath)
      window?.webContents.send('guide:projectMetadata', metadata)
      sendLog(window, 'info', `Project scanned: ${metadata.fileCount} files found`)

      // Analyze key files
      window?.webContents.send('guide:loading', '正在分析关键文件...')
      sendLog(window, 'info', 'Analyzing key files...')
      const filesToAnalyze = [...metadata.entryFiles].slice(0, 15)
      const fileAnalyses = []

      for (const file of filesToAnalyze) {
        try {
          const fullPath = path.join(projectPath, file)
          const analysis = await analyzeFile(fullPath)
          fileAnalyses.push(analysis)
        } catch (err) {
          sendLog(window, 'warn', `Failed to analyze file: ${file}`)
        }
      }
      sendLog(window, 'info', `Analyzed ${fileAnalyses.length} files`)

      // Generate learning path
      window?.webContents.send('guide:loading', '正在生成学习路径...')
      sendLog(window, 'info', 'Generating learning path with AI...')

      const systemPrompt = buildSystemPrompt()
      const learnPrompt = buildLearnPrompt(metadata, fileAnalyses)
      const response = await claudeClient.complete(systemPrompt, learnPrompt)
      const learningPath = parseJsonResponse(response)
      learningPath.generatedAt = new Date().toISOString()

      sendLog(window, 'info', `Learning path generated: ${learningPath.phases.length} phases`)
      window?.webContents.send('guide:learningPath', learningPath)

      // Explain first file - find the first existing file
      let firstFile = null
      let firstFilePath = null

      for (const phase of learningPath.phases) {
        for (const file of phase.files) {
          const fullPath = resolveFilePath(file.path)
          if (await fileExists(fullPath)) {
            firstFile = file
            firstFilePath = fullPath
            break
          } else {
            sendLog(window, 'warn', `File not found, skipping: ${file.path}`)
          }
        }
        if (firstFile) break
      }

      if (firstFile && firstFilePath) {
        sendLog(window, 'info', `Explaining first file: ${firstFile.path}`)
        await new Promise(resolve => setTimeout(resolve, 500))

        // Check cache first
        const cached = getCachedExplanation(firstFilePath)
        if (cached) {
          sendLog(window, 'info', 'Using cached explanation')
          window?.webContents.send('guide:explanation', {
            explanation: cached,
            filePath: firstFilePath
          })
          window?.webContents.send('guide:loading', '')
          return { success: true }
        }

        window?.webContents.send('guide:loading', '正在分析文件...')
        const analysis = await analyzeFile(firstFilePath)
        let code = await fs.readFile(firstFilePath, 'utf-8')

        // Limit code size
        const maxLines = 3000
        const lines = code.split('\n')
        if (lines.length > maxLines) {
          code = lines.slice(0, maxLines).join('\n') + '\n// ... (truncated)'
        }

        window?.webContents.send('guide:loading', '正在解释代码...')

        const explainPrompt = buildExplainPrompt({
          projectMetadata: metadata,
          targetFile: analysis,
          targetCode: code
        }, { level: 3 })

        const explanationResponse = await claudeClient.complete(systemPrompt, explainPrompt)
        const explanation = parseJsonResponse(explanationResponse)

        // Cache the explanation
        setCachedExplanation(firstFilePath, explanation)
        sendLog(window, 'info', 'Explanation generated and cached')

        window?.webContents.send('guide:explanation', {
          explanation,
          filePath: firstFilePath
        })
      } else {
        sendLog(window, 'error', 'No valid files found in learning path')
      }

      window?.webContents.send('guide:loading', '')
      sendLog(window, 'info', 'Guide started successfully')

      return { success: true }
    } catch (error: any) {
      log.error('Guide error:', error)
      sendLog(window, 'error', `Error: ${error.message}`)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })

  // Explain file
  ipcMain.handle('guide:explainFile', async (event, filePath: string) => {
    const window = BrowserWindow.fromWebContents(event.sender)

    try {
      // Check if file exists
      if (!(await fileExists(filePath))) {
        sendLog(window, 'error', `File not found: ${filePath}`)
        throw new Error(`文件不存在: ${filePath}`)
      }

      // Check cache first
      const cached = getCachedExplanation(filePath)
      if (cached) {
        sendLog(window, 'info', `Using cached explanation for: ${path.basename(filePath)}`)
        window?.webContents.send('guide:explanation', { explanation: cached, filePath })
        window?.webContents.send('guide:loading', '')
        return { success: true, cached: true }
      }

      window?.webContents.send('guide:loading', '正在分析文件...')
      sendLog(window, 'info', `Analyzing file: ${path.basename(filePath)}`)

      const analysis = await analyzeFile(filePath)
      let code = await fs.readFile(filePath, 'utf-8')

      const maxLines = 3000
      const lines = code.split('\n')
      if (lines.length > maxLines) {
        code = lines.slice(0, maxLines).join('\n') + '\n// ... (truncated)'
      }

      window?.webContents.send('guide:loading', '正在解释代码...')

      // Get project metadata from previous scan
      if (!currentProjectPath) {
        throw new Error('No project path set')
      }
      const metadata = await scanProject(currentProjectPath)

      const systemPrompt = buildSystemPrompt()
      const explainPrompt = buildExplainPrompt({
        projectMetadata: metadata,
        targetFile: analysis,
        targetCode: code
      }, { level: 3 })

      const response = await claudeClient!.complete(systemPrompt, explainPrompt)
      const explanation = parseJsonResponse(response)

      // Cache the explanation
      setCachedExplanation(filePath, explanation)
      sendLog(window, 'info', 'Explanation generated and cached')

      window?.webContents.send('guide:explanation', { explanation, filePath })
      window?.webContents.send('guide:loading', '')

      return { success: true, cached: false }
    } catch (error: any) {
      log.error('Explain file error:', error)
      sendLog(window, 'error', `Error: ${error.message}`)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })

  // Ask question
  ipcMain.handle('guide:askQuestion', async (event, question: string, context: any) => {
    const window = BrowserWindow.fromWebContents(event.sender)

    try {
      window?.webContents.send('guide:loading', '思考中...')
      sendLog(window, 'info', `User question: ${question.substring(0, 50)}...`)

      const systemPrompt = buildSystemPrompt()
      const chatPrompt = buildChatPrompt(context, [])
      const response = await claudeClient!.complete(systemPrompt, chatPrompt)

      window?.webContents.send('guide:loading', '')
      sendLog(window, 'info', 'Answer generated')

      return response
    } catch (error: any) {
      log.error('Ask question error:', error)
      sendLog(window, 'error', `Error: ${error.message}`)
      event.sender.send('guide:error', error.message)
      throw error
    }
  })
}
